var storyContent = {"inkVersion":21,"root":[["\n","\n","\n","\n","\n",{"->":"night_0"},["done",{"#f":5,"#n":"g-0"}],null],"done",{"night_0":[{"->":".^.the_call"},{"the_call":[["^Tuesday. 11:47 PM.","\n","^The phone echoes through your apartment.","\n","^You've been with the Order of the Night for three years now. Long enough to know that when Silas Ward calls before midnight, it's not good. And when he calls after midnight, it's even worse.","\n","^This one is right on the line.","\n","ev","str","^Pick up the phone.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Let it ring a second longer, then pick up.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n",{"->":".^.^.g-0"},{"#f":5}],"c-1":["\n","ev",{"VAR?":"silas_trust"},1,"-",{"VAR=":"silas_trust","re":true},"/ev","^You let it ring three times. A small rebellion. Silas will notice it.","\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^\"It's Ward.\" His voice is flat, curt, the way it always is. You've never heard the man laugh and you're not sure if he can. \"We have a situation. Get here now.\"","\n","^\"Now?\"","\n","^\"Now.\"","\n",{"->":"night_0.headquarters"},{"#f":5}]}],{"#f":1}],"headquarters":[["^For an ancient order, the headquarters is not impressive by any means. A rented office above a nail salon inside of a Las Vegas strip mall. Buzzing fluorescent lights. A coffee maker that's been brewing the same pot since before you were born. Maybe since before Silas was born.","\n","^Silas is standing at the end of a long table with an open folder. Paper. He doesn't trust anything digital. You see a map, two photographs, and a new cell phone still in its box.","\n","^He picks up one photograph and holds it up.","\n","^\"Mara Castillo. Do you know her?\"","\n",["ev",{"^->":"night_0.headquarters.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"We've met before, briefly.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.headquarters.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I know the name\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.headquarters.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"She handled the Winslow case, right?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_0.headquarters.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"c-1":["ev",{"^->":"night_0.headquarters.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"c-2":["ev",{"^->":"night_0.headquarters.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^\"Three weeks ago, I sent Mara to investigate a location in Nevada. A year-round haunted attraction called The Hollows. It's built inside an old mine outside of a town called Veinrock. She went in undercover, hired as a scare actor.\"","\n","^He slides the other photograph across the table. It's a promotional shot of the entrance to The Hollows. A massive mine shaft mouth, lit in red, fog spilling out. The tagline reads: THE MOST TERRIFYING EXPERIENCE IN AMERICA. OPEN 365 NIGHTS A YEAR.","\n","^\"For the first ten days, she reported in regularly. Standard observations. Unnaturally large attraction. Extends deep underground. Some areas restricted to senior staff. Then her reports became... odd.\"","\n",["ev",{"^->":"night_0.headquarters.0.g-0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-3","flg":18},{"s":["^\"Odd how?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.headquarters.0.g-0.7.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-4","flg":18},{"s":["^\"Define odd.\"",{"->":"$r","var":true},null]}],{"c-3":["ev",{"^->":"night_0.headquarters.0.g-0.c-3.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-1"},{"#f":5}],"c-4":["ev",{"^->":"night_0.headquarters.0.g-0.c-4.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.7.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^\"She said the place felt wrong. Not haunted. She's handled hauntings. She said it felt... hungry.\"","\n",["ev",{"^->":"night_0.headquarters.0.g-1.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-5","flg":18},{"s":["^\"Hungry?\"",{"->":"$r","var":true},null]}],"ev","str","^Keep listening.","/str","/ev",{"*":".^.c-6","flg":20},{"c-5":["ev",{"^->":"night_0.headquarters.0.g-1.c-5.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-2"},{"#f":5}],"c-6":["\n",{"->":".^.^.^.g-2"},{"#f":5}],"#f":5}],"g-2":["^\"She described a persistent low-frequency hum in the lower tunnels. Guests experiencing terror disproportionate to the stimuli. And she mentioned a smell: ozone and copper coming from below the attraction level.\"","\n","^He pauses.","\n","^\"Her last report was twenty days ago. I've heard nothing since.\"","\n",["ev",{"^->":"night_0.headquarters.0.g-2.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-7","flg":18},{"s":["^\"Did you try to reach her?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.headquarters.0.g-2.7.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-8","flg":18},{"s":["^\"What did you do?\"",{"->":"$r","var":true},null]}],{"c-7":["ev",{"^->":"night_0.headquarters.0.g-2.c-7.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-3"},{"#f":5}],"c-8":["ev",{"^->":"night_0.headquarters.0.g-2.c-8.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.7.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-3"},{"#f":5}],"#f":5}],"g-3":["^\"I called The Hollows directly. Asked for Mara. They said no one by that name works there. I gave them her description. Nothing. I asked about recent hires in the past month. They told me there's nothing else they could help me with.\"","\n","^The facts settle in the air.","\n","^\"Mara Castillo worked there for ten days. She reported to me from inside. And now they are saying she never existed.\"","\n",{"->":"night_0.headquarters_answers"},{"#f":5}]}],{"#f":1}],"headquarters_answers":[[["ev",{"^->":"night_0.headquarters_answers.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_0.headquarters_cover_name"},"!","/ev",{"*":".^.^.c-0","flg":19},{"s":["^\"Could she have used a cover name?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.headquarters_answers.0.1.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str",{"CNT?":"night_0.headquarters_record"},"!","/ev",{"*":".^.^.c-1","flg":23},{"s":["^\"That's not possible.",{"->":"$r","var":true},null]}],"ev","str","^Wait for him to continue.","/str",{"CNT?":".^.^.^.headquarters_wait"},"!","/ev",{"*":".^.c-2","flg":21},{"c-0":["ev",{"^->":"night_0.headquarters_answers.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":"night_0.headquarters_cover_name"},{"#f":5}],"c-1":["ev",{"^->":"night_0.headquarters_answers.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.1.s"},[{"#n":"$r2"}],"^ There has to be a record.\"","\n",{"->":"night_0.headquarters_record"},{"#f":5}],"c-2":["^ You wait.","\n",{"->":"night_0.headquarters_wait"},{"#f":5}]}],{"#f":1}],"headquarters_cover_name":["^\"She did. I assigned one to her, 'Elena Voss.\" No record of that name.\"","\n",{"->":".^.^.headquarters_answers"},{"#f":1}],"headquarters_record":["^\"That's what I thought. But I assigned our digital forensics team to look remotely at the employee databases. No payroll records. We checked the security footage but the cameras recycle every 2 days. Convenient.\"","\n",{"->":".^.^.headquarters_answers"},{"#f":1}],"headquarters_wait":[["^Silas is unusually quiet. He always has an answer, even if it's \"insufficient data.\"","\n",["^\"I think something there is capable of making people disappear. But I don't know how.\"","\n",{"->":"night_0.the_assignment"},{"#f":5,"#n":"g-0"}],null],{"#f":1}],"the_assignment":["^\"Here's what we do know.\"","\n","^He beckons you over next to him and points to the map. It's a topographic survey of the area around Veinrock, Nevada.","\n","^\"Veinrock was a silver mining town. In 1973, a sinkhole collapsed the main shaft of the Aldrich Silver Mine. Forty-eight miners were killed. The remaining residents emptied out within a year. It became a ghost town for twenty-five years.\"","\n","^His finger thuds on the map.","\n","^\"In 1998, a company called HorrorCo Entertainment purchased the mine and the surrounding property. Built a haunted attraction inside of the tunnels. Named it The Hollows. And they've been operating year-round ever since.\"","\n",{"->":".^.^.the_assignment_questions"},{"#f":1}],"the_assignment_questions":[[["ev",{"^->":"night_0.the_assignment_questions.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str",{"CNT?":"night_0.the_year_round"},"!","/ev",{"*":".^.^.c-0","flg":23},{"s":["^\"Year round?",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.the_assignment_questions.0.1.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_0.the_horrorco"},"!","/ev",{"*":".^.^.c-1","flg":19},{"s":["^\"What do we know about HorrorCo?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.the_assignment_questions.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_0.the_flagged"},"!","/ev",{"*":".^.^.c-2","flg":19},{"s":["^\"Why did the Order flag this location?\"",{"->":"$r","var":true},null]}],"ev","str","^Nod.","/str","/ev",{"*":".^.c-3","flg":20},{"c-0":["ev",{"^->":"night_0.the_assignment_questions.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"^ That's unusual for a haunt.\"","\n",{"->":"night_0.the_year_round"},{"#f":5}],"c-1":["ev",{"^->":"night_0.the_assignment_questions.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.1.s"},[{"#n":"$r2"}],"\n",{"->":"night_0.the_horrorco"},{"#f":5}],"c-2":["ev",{"^->":"night_0.the_assignment_questions.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n",{"->":"night_0.the_flagged"},{"#f":5}],"c-3":["\n",{"->":"night_0.the_ask"},{"#f":5}]}],{"#f":1}],"the_year_round":["^\"Yes. Most haunted attractions are seasonal. Halloween. Maybe a few weekends in the fall. The Hollows runs every single night. And it's not lacking for business. Visitors come from across the country. There's a waitlist.\"","\n",{"->":".^.^.the_assignment_questions"},{"#f":1}],"the_horrorco":["^\"Almost nothing. They're incorporated in Delaware. Shell company structure. No public-facing leadership. No press interviews. No social media presence except for marketing. For a company running the most popular haunted attraction in the country, they are remarkably invisible.\"","\n",{"->":".^.^.the_assignment_questions"},{"#f":1}],"the_flagged":["^\"Disappearances. Over the past three years, at least eight people connected to The Hollows have vanished. Guests, employees, a local contractor. Local police investigated and found nothing. All cold cases, closed. The pattern caught our attention.\"","\n",{"->":".^.^.the_assignment_questions"},{"#f":1}],"the_ask":[["^Silas gestures at the boxed phone.","\n","^\"Burner. Encrypted line. My number is the only contact. Report in every twenty-four hours. If I don't hear from you in forty-eight, I'm sending a team.\"","\n","^He pauses.","\n","^\"Your cover is already set up. You've applied for a scare actor position at The Hollows under the name 'Val Rowan.' You start orientation tomorrow. Drive out tonight.\"","\n","^He organizes the files back into the folder. His gaze rises to meet you directly. You're used to concern in his expression, but this is severe.","\n","^\"I need to know what happened to Mara. And I need to know what's inside of that mine. But I want to be clear about priorities.\"","\n",["ev",{"^->":"night_0.the_ask.0.12.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Finding Mara is the priority.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.the_ask.0.13.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Understanding the threat is the priority.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_0.the_ask.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.12.s"},[{"#n":"$r2"}],"\n","ev","str","^find_mara","/str","/ev",{"VAR=":"priority","re":true},"^Silas nods slowly.","\n","^\"Agreed. Whatever is happening at The Hollows, we have an agent unaccounted for. Find her first. The investigation is secondary.\"","\n",{"->":"night_0.the_drive"},{"#f":5}],"c-1":["ev",{"^->":"night_0.the_ask.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.13.s"},[{"#n":"$r2"}],"\n","ev","str","^investigate_paranormal","/str","/ev",{"VAR=":"priority","re":true},"ev",{"VAR?":"silas_trust"},1,"+",{"VAR=":"silas_trust","re":true},"/ev","^Silas nods.","\n","^\"The Order's mission is to identify and contain threats. Mara knew the risks. If we understand what we're dealing with, we're better positioned to help her and anyone else.\"","\n",{"->":"night_0.before_the_drive"},{"#f":5}]}],{"#f":1}],"before_the_drive":[["ev","str","^\"I understand.\"","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_0.the_drive"},{"#f":5}]}],{"#f":1}],"the_drive":[["^1 AM.","\n","^The drive is six hours through the empty Nevada desert highway. Your headlights cut a tunnel through the dark and reflects the occasional pair of animal eyes from the shoulder of the road.","\n","^You think about Mara. You met her once, at an Order debrief in Denver. She was sharp, careful, the kind of person who checked exits when she walked into a room. Not the kind of person who disappears.","\n","^Around 4 AM, you pass a sign: VEINROCK - 43 MILES.","\n","^Around 5 AM, you pass another: THE HOLLOWS - OPEN EVERY NIGHT - YOU WON'T SURVIVE.","\n","^Around 6 AM, just as the sky is turning grey, you see it.","\n","^Veinrock.","\n","ev","str","^Drive through","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_0.veinrock"},{"#f":5}]}],{"#f":1}],"veinrock":[["^A cluster of low buildings along a single main road. A gas station. A motel called THE MINESHAFT INN with a half-lit neon sign. A diner. A gift shop. The town is smaller than you expected.","\n","^The end of the road leads to the base of a low mountain. Even from here, in the grey early morning, you see the arch of the mine entrance. Massive, industrial, hung with arrays of unlit lights and speakers. A banner across the top reads THE HOLLOWS in dripping red letters.","\n","^It's closed. It's quiet. The parking lot is empty.","\n","^But you feel it.","\n","^Something underground. A hum you feel in your chest instead of hearing in your ears. A warmth in the air that doesn't match the rising desert dawn.","\n","^You pull into the Mineshaft Inn. The motel owner, half-asleep and disinterested, hands you a key. Room 6.","\n","^You set your bag down and plug in the burner phone. You draw the shades shut across the window facing the mine entrance at the end of town.","\n","^Orientation is at 2 PM.","\n","^You have six hours.","\n","ev","str","^Try to sleep.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^You're not going to sleep. Explore the town.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Call Silas and confirm you've arrived.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","^You manage a few hours of shallow, restless sleep. You dream about a mine shaft that goes down forever. You wake up feeling slightly more alert.","\n",{"->":"night_0.end_night_0"},{"#f":5}],"c-1":["\n","ev",true,"/ev",{"VAR=":"day_1_gloria","re":true},"^You walk along the main road as the sun comes up. Everything is closed. The town feels like a movie set. Facades with nothing behind them. You notice the diner opens at 7. An older adult woman behind the window turns on lights. You don't go in yet, but you've clocked her.","\n",{"->":"night_0.end_night_0"},{"#f":5}],"c-2":["\n","ev",{"VAR?":"silas_trust"},1,"+",{"VAR=":"silas_trust","re":true},"/ev","^You call Silas. He picks up on one ring.","\n","^\"You're there? Good. Get some rest. Report in after your first shift. And be careful.\"","\n",{"->":"night_0.end_night_0"},{"#f":5}]}],{"#f":1}],"end_night_0":[["^2PM.","\n","^You walk across town to The Hollows.","\n","^The mine entrance is bigger up close. The arch must be at least thirty feet tall. In the daylight, you see the infrastructure: wiring, ventilation ducts, a ticket booth, crowd barriers for the nightly queue. It's a professional operation.","\n","^A sign by the staff entrance reads: NEW HIRE ORIENTATION - REPORT TO OFFICE.","\n","^You push through the door.","\n","^The air changes immediately. Cooler. Damp. And underneath everything, that hum.","\n","^You're inside.","\n","ev","str","^Continue.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"day_1"},{"#f":5}]}],{"#f":1}],"#f":1}],"day_1":[{"->":".^.orientation_entrance"},{"orientation_entrance":[["^The staff entrance leads into a narrow concrete corridor. Fluorescent tubes overhead. The air smells like fog machine fluid and something older underneath: damp stone, copper, earth.","\n","^A laminated sign on the wall reads: ALL STAFF MUST CHECK IN AT FRONT OFFICE BEFORE SHIFT. Another reads: RESTRICTED AREAS ARE OFF-LIMITS. VIOLATORS WILL BE TERMINATED.","\n","ev","str","^That's one way to phrase it.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Keep moving.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^Terminated. You file that word away.","\n",{"->":"day_1.the_office"},{"#f":5}],"c-1":["\n",{"->":"day_1.the_office"},{"#f":5}]}],{"#f":1}],"the_office":[["^The front office is a converted mining foreman's room. You can still see the old riveted iron walls behind the drywall. A desk. Filing cabinets. A bank of security monitors showing camera feeds from inside the attraction, all currently dark.","\n","^A man stands up from behind the desk. Mid-50s. Polo shirt with the HorrorCo logo, a stylized H with claw marks through it. He's got the energy of a car dealership manager: big smile, firm handshake, eyes that are already sizing you up.","\n","^\"You must be Val! Dale Ruskin, general manager. Welcome to The Hollows.\"","\n","ev","str","^\"Nice to meet you.\"","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^\"Thanks for having me. I'm excited to start.\"","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^\"Likewise, likewise. We're glad to have you. Always need fresh faces around here.\" He laughs at something that isn't a joke.","\n",{"->":"day_1.dale_intro"},{"#f":5}],"c-1":["\n","^\"Love the enthusiasm. That's what we look for. Enthusiasm and reliability.\" He holds eye contact a beat too long on that last word.","\n",{"->":"day_1.dale_intro"},{"#f":5}]}],{"#f":1}],"dale_intro":[["^\"So, Val. Before we get into the tour and the paperwork, tell me: why The Hollows? We're not exactly easy to get to.\"","\n",["ev",{"^->":"day_1.dale_intro.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str","/ev",{"*":".^.^.c-0","flg":22},{"s":["^\"I've always been into haunts.",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.dale_intro.0.3.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str","/ev",{"*":".^.^.c-1","flg":22},{"s":["^\"Honestly, I needed a change of scenery.",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.dale_intro.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str","/ev",{"*":".^.^.c-2","flg":22},{"s":["^\"I heard the rumors.",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.dale_intro.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"^ This is the best in the country, right?\"","\n","^Dale beams. \"The best in the country. Maybe the world. And I'm not just saying that because I run the place.\" He is absolutely saying that because he runs the place.","\n",{"->":"day_1.dale_tour_start"},{"#f":5}],"c-1":["ev",{"^->":"day_1.dale_intro.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.3.s"},[{"#n":"$r2"}],"^ Saw the listing online.\"","\n","^\"A lot of people end up here that way. Looking for something different.\" His smile doesn't waver. \"They usually find it.\"","\n",{"->":"day_1.dale_tour_start"},{"#f":5}],"c-2":["ev",{"^->":"day_1.dale_intro.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"^ People say this place is the real deal.\"","\n","^Dale's expression doesn't change, but something behind his eyes shifts. Just for a moment. Then the smile is back, wider.","\n","^\"People say a lot of things. That's the beauty of the haunt business. The line between what's real and what's performance? That's where the magic is.\"","\n","ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev",{"->":"day_1.dale_tour_start"},{"#f":5}]}],{"#f":1}],"dale_tour_start":[["^\"Alright. Let me show you the operation.\"","\n","^Dale grabs a clipboard and leads you out of the office and into the main corridor. In daylight (or rather, in the work lights that substitute for daylight down here) The Hollows looks like a construction site crossed with a theater backstage. Exposed wiring. Plywood flats painted to look like stone walls. Animatronic rigs hanging limp from the ceiling.","\n","^\"We run about thirty scare zones across three levels,\" Dale explains, walking briskly. \"Upper tunnels, mid-level, and the deep rooms. You'll start in the uppers. That's where most new hires go.\"","\n",["ev",{"^->":"day_1.dale_tour_start.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What's in the deep rooms?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.dale_tour_start.0.7.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"How many actors per shift?\"",{"->":"$r","var":true},null]}],"ev","str","^Just follow and observe.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"day_1.dale_tour_start.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","^Dale doesn't break stride. \"The deep rooms are for senior actors. High-intensity scares. Mechanical rigs, water effects, the works. You'll get there eventually.\" He says it like a promise. Or a warning.","\n",{"->":"day_1.the_tour"},{"#f":5}],"c-1":["ev",{"^->":"day_1.dale_tour_start.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.7.s"},[{"#n":"$r2"}],"\n","^\"We run about forty actors on a full night, plus tech crew, plus floor managers. It's a big operation.\" He says this with pride, but forty actors for a haunted attraction this size seems thin.","\n",{"->":"day_1.the_tour"},{"#f":5}],"c-2":["\n","^You take in the details as Dale talks. The corridors are wider than you expected. The ceilings are high: original mine architecture, reinforced but not rebuilt. This place wasn't just converted. It was barely modified. The mine is the attraction.","\n",{"->":"day_1.the_tour"},{"#f":5}]}],{"#f":1}],"the_tour":[["^Dale leads you through a winding route. Even with the work lights on, the tunnels feel oppressive. The walls are rough stone, real mine walls, not set dressing. Every so often you pass a steel door marked with a HorrorCo logo and a keycard reader.","\n","^\"Storage,\" Dale says when you glance at one. \"Equipment, props, spare parts. Nothing exciting.\"","\n","^The doors are spaced irregularly. Some corridors have three in a row. Others have none for long stretches. There's no pattern you can see.","\n",["ev",{"^->":"day_1.the_tour.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"That's a lot of storage.\"",{"->":"$r","var":true},null]}],"ev","str","^Note the door locations mentally.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["ev",{"^->":"day_1.the_tour.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","^\"Big operation, big inventory.\" Dale doesn't elaborate.","\n",{"->":"day_1.meet_bex"},{"#f":5}],"c-1":["\n","^You count. Fourteen locked doors between the office and the first scare zone. That's more infrastructure than any haunted attraction needs.","\n",{"->":"day_1.meet_bex"},{"#f":5}]}],{"#f":1}],"meet_bex":[["^You notice the temperature dropping as you walk deeper. Not dramatically, just a degree or two, steady, like descending into something.","\n","^Dale rounds a corner and you nearly walk into someone.","\n","^They're sitting on an overturned crate in the middle of a scare zone, eating a granola bar. Black jeans, black hoodie, pale makeup smudged around their eyes from last night's shift. Or maybe the night before. They look up without surprise, as if they'd been expecting you.","\n","^\"Bex, this is Val. New hire. Val, this is Bex. They've been with us for...\" Dale pauses, and for a second he looks genuinely uncertain. \"How long has it been, Bex?\"","\n","^Bex chews. Thinks.","\n","^\"A while.\"","\n","^Dale laughs. \"A while. Bex is one of our best. They'll show you the ropes tonight.\"","\n",["ev",{"^->":"day_1.meet_bex.0.14.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Hey. Nice to meet you.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.meet_bex.0.15.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Looking forward to working together.\"",{"->":"$r","var":true},null]}],"ev","str","^Just nod.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"day_1.meet_bex.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.14.s"},[{"#n":"$r2"}],"\n","^Bex nods. \"Likewise.\" Their eyes flick to Dale, then back to you. Something passes across their face that you can't read.","\n",{"->":"day_1.bex_aside"},{"#f":5}],"c-1":["ev",{"^->":"day_1.meet_bex.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.15.s"},[{"#n":"$r2"}],"\n","^\"Sure.\" Bex's voice is flat. Not hostile, just... distant. Like they're listening to something else.","\n",{"->":"day_1.bex_aside"},{"#f":5}],"c-2":["\n","^You nod. Bex nods back. There's a stillness to them that feels practiced. Or maybe involuntary.","\n",{"->":"day_1.bex_aside"},{"#f":5}]}],{"#f":1}],"bex_aside":[["^Dale claps his hands. \"Alright, I've got paperwork to finish up. Bex, give Val the actor's tour? Show them the upper zones, the break room, the usual.\"","\n","^He turns to you. \"Come find me in the office when you're done. We'll get your contract signed and your schedule sorted.\"","\n","^Dale leaves. His footsteps echo and fade.","\n","^Bex watches him go. They wait until the sound disappears completely.","\n","^\"So,\" Bex says. \"First haunt job?\"","\n",["ev",{"^->":"day_1.bex_aside.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"First professional one, yeah.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.bex_aside.0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I've done a few seasonal gigs.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.bex_aside.0.12.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Is Dale always like that?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.bex_aside.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^\"Professional.\" Bex almost smiles. \"That's one word for it.\"","\n",{"->":"day_1.bex_tour"},{"#f":5}],"c-1":["ev",{"^->":"day_1.bex_aside.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^\"Seasonal.\" Bex says the word like it's from another language. \"Right. Most haunts are seasonal.\"","\n",{"->":"day_1.bex_tour"},{"#f":5}],"c-2":["ev",{"^->":"day_1.bex_aside.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.12.s"},[{"#n":"$r2"}],"\n","^Bex considers this. \"Dale is... consistent. He's always exactly like that. Every single day. Which, if you think about it, is kind of weird.\"","\n",{"->":"day_1.bex_tour"},{"#f":5}]}],{"#f":1}],"bex_tour":[["^Bex hops off the crate and starts walking. Their pace is slower than Dale's, more deliberate. They point things out as you go.","\n","^\"Break room's down that hall. Fridge, microwave, lockers. Lock your stuff. Things go missing sometimes.\"","\n","^\"Costume room is past the break room. You'll get fitted before your first shift tonight. Mostly something to go over your black clothes, face paint, maybe a mask depending on your zone.\"","\n","^They stop at an intersection. Left goes upward; you can feel the grade. Right goes down.","\n","^\"Left is the upper scare zones. That's where you'll be tonight. Right goes to mid-level.\"","\n",["ev",{"^->":"day_1.bex_tour.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"And below mid-level?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.bex_tour.0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"What zone are you in?\"",{"->":"$r","var":true},null]}],"ev","str","^Follow their lead.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"day_1.bex_tour.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^Bex doesn't answer immediately. They look down the right corridor. The work lights end about fifty feet in, replaced by a dim amber glow.","\n","^\"Below mid-level is deep rooms. You don't go there.\"","\n","^\"Dale said it's for senior actors.\"","\n","^\"Dale says a lot of things.\" Bex turns left. \"Come on.\"","\n",{"->":"day_1.upper_zones"},{"#f":5}],"c-1":["ev",{"^->":"day_1.bex_tour.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^\"I rotate. Uppers, mids, wherever they need me.\" A pause. \"I used to work the deep rooms. A while ago.\"","\n","^\"What was that like?\"","\n","^Bex starts walking left, toward the upper zones. \"Dark,\" they say, and don't elaborate.","\n",{"->":"day_1.upper_zones"},{"#f":5}],"c-2":["\n","^Bex turns left without hesitation. As you follow, you glance down the right corridor. The work lights thin out quickly. The walls narrow. The air coming from that direction is warmer.","\n",{"->":"day_1.upper_zones"},{"#f":5}]}],{"#f":1}],"upper_zones":[["^The upper scare zones are, in daylight, almost comically mundane. Plywood corridors painted black. Fog machine nozzles built into the floor. Hidden alcoves where actors wait. Speakers wired into the walls. Motion sensors trigger strobe lights and sound cues.","\n","^Bex walks you through three zones: THE SHAFT, THE COLLAPSE, and THE BURIED.","\n","^\"Creative naming,\" you say.","\n","^\"HorrorCo has a theme.\" Bex runs a hand along the tunnel wall. Real stone, not plywood. \"Mining disaster. Cave-ins. Being trapped underground. Guests love it.\"","\n",["ev",{"^->":"day_1.upper_zones.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str","/ev",{"*":".^.^.c-0","flg":22},{"s":["^\"Do you know the history?",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.upper_zones.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Have you ever seen anything actually... strange in here?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.upper_zones.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Guests ever get hurt?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.upper_zones.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"^ The actual mine?\"","\n","^Bex stops walking. \"The Aldrich Mine. 1973. Sinkhole took the whole main shaft. Killed...\" They pause, eyes unfocused. \"A lot of people.\"","\n","^The way they say it. Not like they read about it. Like they're trying to remember the number and can't.","\n",{"->":"day_1.end_of_tour"},{"#f":5}],"c-1":["ev",{"^->":"day_1.upper_zones.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n","^Bex's pace doesn't change. \"Define strange. I work in a haunted house. Everything's strange. That's the product.\"","\n","^\"I mean strange that's not part of the show.\"","\n","^A beat of silence.","\n","^\"Ask me again after you've worked a few shifts.\"","\n",{"->":"day_1.end_of_tour"},{"#f":5}],"c-2":["ev",{"^->":"day_1.upper_zones.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^\"Sometimes. People trip, run into walls, panic. Standard haunt stuff. We're trained in de-escalation.\" Bex recites this like they've said it a hundred times.","\n","^\"I've heard rumors about worse than that.\"","\n","^Bex looks at you. Really looks at you, for the first time.","\n","^\"Rumors are good for business.\"","\n",{"->":"day_1.end_of_tour"},{"#f":5}]}],{"#f":1}],"end_of_tour":[["^Bex walks you back toward the office corridor.","\n","^\"One more thing.\" They stop. \"When you're working your zone, stay in your zone. Don't wander. Especially after midnight. The layout can get...\" They search for the word. \"Confusing.\"","\n",["ev",{"^->":"day_1.end_of_tour.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Confusing how?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.end_of_tour.0.5.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Is that standard advice?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.end_of_tour.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Thanks for the heads up.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.end_of_tour.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^\"You'll think you know where you are, and then you won't. Happens to everyone at first. Just stay put and wait for the shift to end.\"","\n","^That doesn't sound like normal new-hire advice.","\n",{"->":"day_1.sign_paperwork"},{"#f":5}],"c-1":["ev",{"^->":"day_1.end_of_tour.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.5.s"},[{"#n":"$r2"}],"\n","^\"It's my advice.\" Bex meets your eyes. \"Take it or don't.\"","\n",{"->":"day_1.sign_paperwork"},{"#f":5}],"c-2":["ev",{"^->":"day_1.end_of_tour.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","ev",{"VAR?":"bex_relationship"},1,"+",{"VAR=":"bex_relationship","re":true},"/ev","^Bex nods once. They turn to go, then stop.","\n","^\"Val? The hum. You hear it, right?\"","\n","^Before you can answer, they walk away.","\n",{"->":"day_1.sign_paperwork"},{"#f":5}]}],{"#f":1}],"sign_paperwork":[["^You find Dale in the office. He's got a stack of paperwork ready: employment contract, NDA, liability waiver. Standard forms, except for the NDA, which is unusually comprehensive.","\n","^You scan the key clauses:","\n","^\"Employee agrees not to disclose any details of attraction design, layout, or operational procedures...\"","\n","^\"Employee acknowledges that The Hollows experience may include intense sensory stimulation including but not limited to extreme darkness, physical contact, confined spaces, and disorientation...\"","\n","^\"Employee waives all claims against HorrorCo Entertainment LLC for psychological distress, injury, or...\"","\n","^The next word catches your eye.","\n","^\"...disappearance.\"","\n",["ev",{"^->":"day_1.sign_paperwork.0.14.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"This waiver mentions disappearance.\"",{"->":"$r","var":true},null]}],"ev","str","^Read it again to make sure you read it right.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Keep reading without reacting.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"day_1.sign_paperwork.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.14.s"},[{"#n":"$r2"}],"\n","^Dale doesn't blink. \"Legal boilerplate. Our lawyers are thorough. You know how it is. Cover every base, no matter how unlikely.\" His smile is steady.","\n",{"->":"day_1.sign_or_not"},{"#f":5}],"c-1":["\n","^Disappearance. That's what it says. Right there between \"injury\" and a clause about \"unforeseen metaphysical phenomena,\" which you also have questions about.","\n",{"->":"day_1.sign_or_not"},{"#f":5}],"c-2":["\n","^You file it away. Disappearance. Unforeseen metaphysical phenomena. This is not a standard liability waiver.","\n",{"->":"day_1.sign_or_not"},{"#f":5}]}],{"#f":1}],"sign_or_not":[["^Dale is watching you read. Patient. Still smiling.","\n","^\"Any questions before you sign?\"","\n",["ev",{"^->":"day_1.sign_or_not.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What are 'unforeseen metaphysical phenomena'?\"",{"->":"$r","var":true},null]}],"ev","str","^Sign it.","/str","/ev",{"*":".^.c-1","flg":20},["ev",{"^->":"day_1.sign_or_not.0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Seems pretty thorough for a haunted house.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.sign_or_not.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^\"You ever been in a haunt so scary you felt like you left your body? Like reality shifted?\" Dale chuckles. \"Guests have tried to sue over panic attacks, dissociative episodes, that sort of thing. The clause protects us. Nothing more.\"","\n","ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev",{"->":"day_1.sign_it"},{"#f":5}],"c-1":["\n","^You sign. You're here to investigate, not to be protected by paperwork. Whatever rights you're waiving, the Order will handle the legal side.","\n",{"->":"day_1.post_sign"},{"#f":5}],"c-2":["ev",{"^->":"day_1.sign_or_not.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^\"We're not just a haunted house, Val. We're the most terrifying experience in America.\" He taps the promotional photo on his desk. \"That comes with liability.\"","\n",{"->":"day_1.sign_it"},{"#f":5}]}],{"#f":1}],"sign_it":[["ev","str","^Sign the paperwork.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"day_1.post_sign"},{"#f":5}]}],{"#f":1}],"post_sign":["^Dale takes the signed forms and files them immediately. He hands you a schedule. Your first shift starts tonight at 7 PM.","\n","^\"Costume fitting at 6. Bex will get you set up. Show starts at 8, but we do run-throughs first. You'll be in Zone 2: The Collapse.\"","\n","^He extends his hand. You shake it.","\n","^\"Welcome to The Hollows, Val. You're going to love it here.\"","\n","^His grip is firm. A beat too long.","\n","^\"Everyone does.\"","\n",{"->":".^.^.pre_night_1"},{"#f":1}],"pre_night_1":["^You step outside. Late afternoon. The desert sun is already dropping toward the mountains. You have a few hours before your shift.","\n","ev",{"VAR?":"day_1_gloria"},"/ev",[{"->":".^.b","c":true},{"b":["\n","^You think about the woman you saw in the diner this morning. It's still open. The sign reads ALDRICH'S.","\n",{"->":".^.^.^.6"},null]}],"nop","\n",{"->":".^.^.pre_night_1_hub"},{"#f":1}],"pre_night_1_hub":[["ev","str","^Go to the diner.","/str",{"VAR?":"day_1_gloria"},{"CNT?":"day_1.gloria_intro"},"!","&&","/ev",{"*":".^.c-0","flg":21},"ev","str","^Go back to the motel and prepare.","/str",{"CNT?":"day_1.pre_night_1_motel"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Call Silas to report.","/str",{"CNT?":"day_1.pre_night_1_silas"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^Head to your shift.","/str","/ev",{"*":".^.c-3","flg":20},{"c-0":["\n",{"->":"day_1.gloria_intro"},{"#f":5}],"c-1":["\n",{"->":"day_1.pre_night_1_motel"},{"#f":5}],"c-2":["\n",{"->":"day_1.pre_night_1_silas"},{"#f":5}],"c-3":["\n",{"->":"day_1.to_night_1"},{"#f":5}]}],{"#f":1}],"pre_night_1_motel":["^You walk back to the Mineshaft Inn. Room 6. You sit on the bed and go over what you've learned: the locked doors, the deep rooms, Bex's warning, the waiver. You write it all down in your notebook in the Order's shorthand.","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ You also note that you haven't found any trace of Mara yet. No one has mentioned a recent departure. It's like she was never here. Because according to them, she wasn't.",{"->":".^.^.^.10"},null]}],"nop","\n",{"->":".^.^.pre_night_1_hub"},{"#f":1}],"pre_night_1_silas":["ev",{"VAR?":"silas_trust"},1,"+",{"VAR=":"silas_trust","re":true},"/ev","^You call from the burner. Silas picks up on the second ring.","\n","^\"I'm in. Start tonight. The place is big, three levels, maybe more. Restricted areas everywhere. The NDA mentions 'disappearance' and 'metaphysical phenomena' in the liability waiver.\"","\n","^Silence on the line.","\n","^\"Stay sharp. And stay on the upper levels for now.\"","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ \"Any trace of Mara?\" he asks. ",{"->":".^.^.^.23"},null]}],[{"->":".^.b"},{"b":["^ \"Focus on the layout first,\" he adds.",{"->":".^.^.^.23"},null]}],"nop","^ \"Report after your shift.\"","\n",{"->":".^.^.pre_night_1_hub"},{"#f":1}],"gloria_intro":[["^The diner is small, warm, and mostly empty. Checkered floor, vinyl booths, a counter with stools. The kind of place that hasn't been updated since the '80s because it didn't need to be.","\n","^The woman behind the counter is in her late 70s, maybe older. She moves with a careful precision. Her eyes are sharp. A name tag reads GLORIA.","\n","^She sets a coffee down in front of you before you ask for one.","\n","^\"You're new.\"","\n","^It's not a question.","\n",["ev",{"^->":"day_1.gloria_intro.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"That obvious?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.gloria_intro.0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I just started at The Hollows.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.gloria_intro.0.12.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"I'm Val.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.gloria_intro.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^\"It's a small town. And people don't come here unless they're visiting The Hollows or working there.\" She studies you. \"You don't look like a tourist.\"","\n","^\"My name is Val.\"","\n",{"->":"day_1.gloria_chat"},{"#f":5}],"c-1":["ev",{"^->":"day_1.gloria_intro.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^Something crosses her face. Fast, then gone. She tops off a coffee cup that's already full.","\n","^\"Another one.\"","\n","^\"My name is Val.\"","\n",{"->":"day_1.gloria_chat"},{"#f":5}],"c-2":["ev",{"^->":"day_1.gloria_intro.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.12.s"},[{"#n":"$r2"}],"\n","^\"Gloria.\" She doesn't offer a handshake. \"You working up at the mine?\"","\n",{"->":"day_1.gloria_chat"},{"#f":5}]}],{"#f":1}],"gloria_chat":[["^Gloria leans against the counter. The diner is empty except for the two of you.","\n","^\"How long you planning to stay?\"","\n",["ev",{"^->":"day_1.gloria_chat.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"As long as they'll have me.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.gloria_chat.0.5.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Haven't decided yet.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.gloria_chat.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Why do you ask?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.gloria_chat.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^Gloria's mouth tightens. \"That's what they all say.\"","\n",{"->":"day_1.gloria_hints"},{"#f":5}],"c-1":["ev",{"^->":"day_1.gloria_chat.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.5.s"},[{"#n":"$r2"}],"\n","^\"Smart. Keep it that way.\"","\n",{"->":"day_1.gloria_hints"},{"#f":5}],"c-2":["ev",{"^->":"day_1.gloria_chat.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","^\"Because people come to work at that place and they stay. Longer than makes sense. Longer than they planned.\" She pauses. \"And some of them don't stay at all. They just... stop being here.\"","\n",{"->":"day_1.gloria_hints"},{"#f":5}]}],{"#f":1}],"gloria_hints":[["^She pours herself a coffee and sits down across from you.","\n","^\"My family built this town. My father owned the mine. I was nine years old when the ground opened up and swallowed it.\"","\n",["ev",{"^->":"day_1.gloria_hints.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"I'm sorry.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.gloria_hints.0.5.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"The sinkhole.\"",{"->":"$r","var":true},null]}],"ev","str","^Listen.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"day_1.gloria_hints.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^She waves the sympathy away. \"It was a long time ago. Or it feels like it should be.\"","\n",{"->":"day_1.gloria_more"},{"#f":5}],"c-1":["ev",{"^->":"day_1.gloria_hints.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.5.s"},[{"#n":"$r2"}],"\n","^\"You did your homework.\" A flicker of something. Respect, maybe. Or wariness.","\n",{"->":"day_1.gloria_more"},{"#f":5}],"c-2":["\n",{"->":"day_1.gloria_more"},{"#f":5}]}],{"#f":1}],"gloria_more":[["^\"Forty-eight men went down that morning. None came back up. They said it was a geological event. Natural causes. But I was there. I heard it.\"","\n","^She wraps both hands around her mug.","\n","^\"A sinkhole doesn't breathe.\"","\n",["ev",{"^->":"day_1.gloria_more.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What do you mean, breathe?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.gloria_more.0.7.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"You think it was something else.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.gloria_more.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"That must have been traumatic for a nine-year-old.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.gloria_more.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","^\"I mean I heard it inhale. The ground shook, and then there was a sound like the earth was taking a breath. And then the men were gone.\"","\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev",{"->":"day_1.gloria_end"},{"#f":5}],"c-1":["ev",{"^->":"day_1.gloria_more.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.7.s"},[{"#n":"$r2"}],"\n","^\"I know it was something else. I've known for fifty years. Nobody wanted to hear it then. Nobody wants to hear it now.\"","\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev",{"->":"day_1.gloria_end"},{"#f":5}],"c-2":["ev",{"^->":"day_1.gloria_more.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n","^\"It was. But the trauma isn't the memory. The trauma is that nobody believed what I heard.\" Her jaw sets. \"I know what I heard.\"","\n",{"->":"day_1.gloria_end"},{"#f":5}]}],{"#f":1}],"gloria_end":[["^Gloria stands, suddenly brisk. The openness closes.","\n","^\"You should eat something before your shift. The meatloaf's decent.\"","\n","^She's done talking. For now. But you can feel it. She has more. She's been waiting to tell someone. She just needs to know you're worth telling.","\n","ev","str","^Eat and head back.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n","^The meatloaf is, in fact, decent.","\n",{"->":"day_1.pre_night_1_hub"},{"#f":5}]}],{"#f":1}],"to_night_1":[["^The sun drops behind the mountain. The Hollows' lights come on: reds, purples, a sickly green. The speakers mounted outside begin a low ambient drone. Cars start pulling into the parking lot. The queue forms.","\n","^Showtime.","\n","ev","str","^Report for your first shift.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_1"},{"#f":5}]}],{"#f":1}],"#f":1}],"night_1":[{"->":".^.costume_fitting"},{"costume_fitting":[["^The costume room is bigger than you expected. More of a wardrobe department than a closet. Racks of costumes line both walls, organized by zone. Shelves of face paint, spirit gum, prosthetic pieces, dental appliances. A row of lit mirrors along the back wall, each station stocked with brushes, sponges, adhesive remover. It smells like greasepaint and latex and sweat.","\n","^The room is already busy. A woman two stations down is being transformed into something with a caved-in ribcage, a silicone chest piece strapped over her torso with visible bone and lung tissue. The detail is surgical. Next to her, a guy is pulling on a full-body suit that makes him look eight feet tall, elongated arms ending in jointed claw extensions. He flexes them, testing the range of motion. Across the room, someone is sitting perfectly still while another actor applies layered prosthetics to their face, building up a texture of blistered, peeling skin. They pop open a small plastic case from their bag and carefully press in a pair of milky white scleral lenses.","\n","^These aren't Halloween store costumes. This is professional creature work. Movie quality.","\n","^Bex is waiting at an open station. They've already laid out your pieces.","\n","ev","str","^Approach them","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_1.bex_fitting"},{"#f":5}]}],{"#f":1}],"bex_fitting":["^\"You're a dead miner. Zone 2, The Collapse.\"","\n","^The costume is a shredded, dust-caked mining jumpsuit, torn and aged to look like it's been underground for decades. Bex helps you into it over your black base layer. It's heavier than it looks: weighted in the shoulders, stiffened in places with dried resin to hold its shape. Over that, a cracked leather tool belt with a dented tin lantern clipped to the hip.","\n","^For the face, Bex sits you down at the mirror and works fast. Grey and blue greasepaint as a base. Darkened hollows around the eyes. A prosthetic gash across the forehead, glued down with spirit gum and blended at the edges. Then the mask: a half-face piece of cracked grey rubber molded to look like a caved-in skull, one eye socket crushed inward. It fits over the top half of your face, leaving your jaw exposed so your scream carries.","\n","^\"You don't talk. You don't chase. You wait in the boo hole until a group passes your trigger point, then you hit the window and scream. Reset. Wait. Repeat.\"","\n",{"->":".^.^.fitting_hub"},{"#f":1}],"fitting_hub":[[["ev",{"^->":"night_1.fitting_hub.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_1.fitting_groups"},"!","/ev",{"*":".^.^.c-0","flg":19},{"s":["^\"How many groups per night?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.fitting_hub.0.1.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_1.fitting_boohole"},"!","/ev",{"*":".^.^.c-1","flg":19},{"s":["^\"What's a boo hole?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.fitting_hub.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_1.fitting_trigger"},"!","/ev",{"*":".^.^.c-2","flg":19},{"s":["^\"What's the trigger point?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.fitting_hub.0.3.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_1.fitting_rules"},"!","/ev",{"*":".^.^.c-3","flg":19},{"s":["^\"Any rules I should know?\"",{"->":"$r","var":true},null]}],"ev","str","^No more questions.","/str","/ev",{"*":".^.c-4","flg":20},{"c-0":["ev",{"^->":"night_1.fitting_hub.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":"night_1.fitting_groups"},{"#f":5}],"c-1":["ev",{"^->":"night_1.fitting_hub.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.1.s"},[{"#n":"$r2"}],"\n",{"->":"night_1.fitting_boohole"},{"#f":5}],"c-2":["ev",{"^->":"night_1.fitting_hub.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n",{"->":"night_1.fitting_trigger"},{"#f":5}],"c-3":["ev",{"^->":"night_1.fitting_hub.0.c-3.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.3.s"},[{"#n":"$r2"}],"\n",{"->":"night_1.fitting_rules"},{"#f":5}],"c-4":["\n",{"->":"night_1.fitting_continued"},{"#f":5}]}],{"#f":1}],"fitting_groups":["^\"On a full night? You'll get maybe sixty, seventy groups through your zone. Peak hours, they're coming every thirty to forty-five seconds. Off-peak, you might wait a few minutes between.\"","\n",{"->":".^.^.fitting_hub"},{"#f":1}],"fitting_boohole":["^\"It's the alcove you hide in. Small space behind the window, just big enough for you to stand in. You wait in there, watch through the slit, and hit the window when they cross your mark.\" They glance at you. \"You'll be spending a lot of time in it. Get comfortable. Or as comfortable as you can.\"","\n",{"->":".^.^.fitting_hub"},{"#f":1}],"fitting_trigger":["^\"There's a mark on the floor. Glow tape, only visible from inside the boo hole. When the first person in the group crosses it, you go. Not before. Timing is everything. Too early and they see it coming. Too late and you're scaring the back of their heads.\"","\n",{"->":".^.^.fitting_hub"},{"#f":1}],"fitting_rules":["^\"Don't touch the guests. Don't break character in front of guests. Don't leave your zone. If a guest says the safe word, which is 'mercy,' you break character, turn on your flashlight, and walk them to the nearest exit. Other than that...\" Bex shrugs. \"Make them scream.\"","\n",{"->":".^.^.fitting_hub"},{"#f":1}],"fitting_continued":[["^You look at yourself in the mirror. Under the fluorescent lights, you can see where the work ends: the spirit gum edge, the seam of the mask, the clean line where the greasepaint stops at your collar. It's impressive up close. From ten feet away in a dark corridor, it would be convincing. In full fog with strobes, it'll be something else entirely.","\n","^Around you, the other actors are finishing up. The woman with the ribcage piece is testing a mechanism that makes the exposed lung inflate and deflate. The tall guy on stilts takes a practice step, his claw arms swaying. The actor with the blistered face has added a set of rotting dental prosthetics and is grinning at the mirror, checking the fit.","\n","^Bex watches your reaction.","\n","^\"It looks different in the dark. Everything does.\"","\n",["ev",{"^->":"night_1.fitting_continued.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"I believe you.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.fitting_continued.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"How do I look?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_1.fitting_continued.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n",{"->":"night_1.run_through"},{"#f":5}],"c-1":["ev",{"^->":"night_1.fitting_continued.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n","^\"Dead.\" Bex says it flat. Then, almost a smile. \"That's the idea.\"","\n",{"->":"night_1.run_through"},{"#f":5}]}],{"#f":1}],"run_through":[["^6:45 PM. The full cast assembles in the break room for the pre-show meeting. About thirty-five actors tonight, plus a handful of tech crew and three floor managers. Dale is at the front, clipboard in hand, radiating enthusiasm.","\n","^\"Good evening, everyone. Full house tonight. We're sold out through midnight. Let's give them something to remember.\"","\n","^He runs through the assignments. Zone by zone, actor by actor. You're Zone 2, Position B: The Collapse, boo hole three. Bex is in Zone 2 as well, Position A. They'll be in the corridor ahead of you, doing a stalker walk to herd groups toward your window.","\n","^\"New hire tonight. Val Rowan, Zone 2 Bravo. Bex, keep an eye on them.\"","\n","^Bex nods.","\n","^Dale finishes the briefing with the same line he apparently uses every night: \"Make it real, people.\"","\n","^The actors disperse. Some are joking, loose, relaxed. A few are stretching like athletes. One woman is already in character, muttering to herself in a corner, her eyes blank. Nobody seems to think this is unusual.","\n","ev","str","^Follow Bex to your zone.","/str","/ev",{"*":".^.c-0","flg":20},["ev",{"^->":"night_1.run_through.0.20.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Does he always say that? 'Make it real'?\"",{"->":"$r","var":true},null]}],{"c-0":["\n",{"->":"night_1.enter_zone"},{"#f":5}],"c-1":["ev",{"^->":"night_1.run_through.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.20.s"},[{"#n":"$r2"}],"\n","^Bex is already walking. \"Every night. Same speech, same words. I've heard it...\" They trail off, counting something internally, then give up. \"A lot.\"","\n",{"->":"night_1.enter_zone"},{"#f":5}]}],{"#f":1}],"enter_zone":[["^Bex leads you through the upper tunnels. The work lights are off now. The show lighting is on: dim red washes, pockets of total darkness, the occasional flicker of a strobe on standby. The fog machines are warming up, a low hiss from the floor vents. The speakers are cycling ambient audio. Dripping water. Distant rumbling. A pickaxe striking stone, over and over.","\n","^The Collapse is a series of narrow corridors designed to look like a mine tunnel after a cave-in. Timber supports lean at bad angles. Rubble (foam, but convincing) is piled against the walls. The ceiling is deliberately low. Guests will have to duck in places.","\n","^Your boo hole is a recessed alcove behind a breakaway window. It's a tight space, barely wide enough for your shoulders. A water bottle and a flashlight sit on a narrow ledge at hip height. A reset button for the window's pneumatic latch is mounted on the wall.","\n","^Bex shows you the mechanics.","\n","^\"Window's spring-loaded. You slam it open, you scream, you hold for one second, then pull it shut and hit the reset. The latch resets in about three seconds. Don't try to hit the next group before it clicks or you'll jam it.\"","\n","^They demonstrate. The window bangs open with a sharp crack. Even expecting it, your pulse jumps.","\n","^\"That's the startle. The sound does half the work. The other half is your scream. Make it sharp. Short. From the chest, not the throat, or you'll blow your voice out by 10.\"","\n",["ev",{"^->":"night_1.enter_zone.0.14.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Got it.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.enter_zone.0.15.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"What's your position like?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.enter_zone.0.16.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"What if the window jams?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_1.enter_zone.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.14.s"},[{"#n":"$r2"}],"\n",{"->":"night_1.first_groups"},{"#f":5}],"c-1":["ev",{"^->":"night_1.enter_zone.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.15.s"},[{"#n":"$r2"}],"\n","^\"I'm in the corridor before you. I step out from behind a support beam, match their walking pace, stay about five feet behind the last person. No sound. When they notice me, they speed up. Right into your window.\" A pause. \"Teamwork.\"","\n",{"->":"night_1.first_groups"},{"#f":5}],"c-2":["ev",{"^->":"night_1.enter_zone.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.16.s"},[{"#n":"$r2"}],"\n","^\"Bang on it with your palm. If it doesn't open, use the flashlight to signal the floor manager. But it won't jam if you time the reset right. Just listen for the click.\"","\n",{"->":"night_1.first_groups"},{"#f":5}]}],{"#f":1}],"first_groups":[["^7:55 PM. Five minutes to showtime.","\n","^You're in the boo hole. The window is shut. The corridor outside is dark except for the faint red wash. The fog is rolling in, ankle-height, cold. The ambient audio has shifted to something lower, more rhythmic. Almost like breathing.","\n","^Through the wall, muffled, you can hear the crowd outside. Hundreds of people in line. Talking, laughing, nervous. Someone screams from the entrance of another zone and there's a ripple of laughter.","\n","^Your radio crackles. Dale's voice: \"Doors open in two. Positions, everyone. Let's have a good night.\"","\n","^You press your back against the rear wall of the alcove. You pull the mask down. You wait.","\n","^The first group enters The Collapse at 8:02 PM.","\n","^You hear them before you see them. Footsteps. Nervous whispers. Someone saying \"oh my God\" already and nothing has happened yet. The fog swirls around their ankles.","\n","^Through the slit in the window, you see Bex step out behind them. Silent. The last person in the group, a tall guy in a baseball cap, glances back and freezes. \"Oh, oh, GO, go go go.\" The group surges forward.","\n","^The first person crosses your glow tape mark.","\n","ev","str","^Hit the window.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_1.first_scare"},{"#f":5}]}],{"#f":1}],"first_scare":[["^You slam the window open. The crack echoes off the stone walls. You scream: short, sharp, from the chest like Bex said.","\n","^The reaction is immediate. The person in front recoils into the person behind them. Someone shrieks. The tall guy in the back is now trying to get to the front. The group compresses, stumbles, then bolts down the corridor and around the corner.","\n","^You pull the window shut. Hit the reset. The latch clicks.","\n","^Silence. Fog. The ambient audio loops.","\n","^Thirty seconds later, the next group comes through.","\n","ev","str","^Reset and go again.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_1.the_rhythm"},{"#f":5}]}],{"#f":1}],"the_rhythm":[["^You find the rhythm.","\n","^Window. Scream. Reset. Wait. Listen for footsteps. Watch for the glow tape. Window. Scream. Reset.","\n","^Every group is different. Some are loud before they even reach you. Teenagers, usually, performing bravery for each other. They scream the hardest when the window hits. Some groups are quiet, cautious, which means the startle lands cleaner. Couples grip each other. Kids (too young to be here, you think, but that's not your call) sometimes cry. Parents pull them through.","\n","^After about twenty groups, your body starts to settle into it. Your shoulders loosen. Your scream becomes consistent: same pitch, same duration, same force. You learn to read the timing by sound alone. Footsteps on gravel. The change in the fog pattern when a body moves through it. Bex's groups always arrive at the same pace, herded to perfection.","\n","^This is the job. Repetition. Precision. Controlled bursts of adrenaline. Reset. Repeat.","\n","^By 9:30, your throat is raw and your right shoulder aches from the window. You take a sip of water. A floor manager's voice comes over the radio: \"Zone 2, pacing is good. Keep it up.\"","\n","ev","str","^Keep working.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Check in with Bex during a gap between groups.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n",{"->":"night_1.late_shift"},{"#f":5}],"c-1":["\n","^You lean out of the boo hole during a lull. Bex is standing at their position, still as stone. You give a thumbs up. They return it without turning their head. They're watching the corridor.","\n","^\"How's your voice?\" they ask, barely above a whisper.","\n","^\"Holding.\"","\n","^\"Good. It gets busy after 10.\"","\n",{"->":"night_1.late_shift"},{"#f":5}]}],{"#f":1}],"late_shift":[["^Bex is right. After 10, the gaps between groups shrink. You're hitting the window every thirty seconds, sometimes faster. The groups are louder, more energized. Weekend crowd. Some of them have been drinking. You can smell it through the fog.","\n","^At 10:47 PM, something different.","\n","^A group comes through. Four people. They're quieter than average. Moving slowly. Bex does the stalker walk behind them, but the last person in the group doesn't react. Doesn't speed up. Doesn't look back.","\n","^They cross the glow tape.","\n","^You hit the window.","\n","^Three of them flinch. Standard reaction. The fourth, the one at the back, turns and looks directly at you through the open window.","\n","^Not startled. Not scared. Just... looking. Their face is calm. They hold eye contact for a long moment.","\n","^Then they turn and walk on.","\n","ev","str","^That was strange. But you've heard that some guests are just like that.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Radio the floor manager.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Ask Bex about it at the next lull.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","^You've seen tough customers before. The ones who come to prove they can't be scared. Arms crossed, smirking, unimpressed. This wasn't that. This person wasn't performing toughness. They were just... absent.","\n",{"->":"night_1.the_figure_appears"},{"#f":5}],"c-1":["\n","^You key the radio. \"Zone 2 Bravo. Last group, person in the back. No reaction. Something felt off.\"","\n","^Static. Then: \"Copy, Zone 2. Probably a repeat visitor. Don't worry about it.\"","\n",{"->":"night_1.the_figure_appears"},{"#f":5}],"c-2":["\n","^You lean out during the next gap. \"That last group. The person at the back.\"","\n","^Bex is quiet for a moment. \"What about them?\"","\n","^\"They looked at me. Through the window. No reaction at all.\"","\n","^\"Some people don't scare.\"","\n","^\"It wasn't that.\"","\n","^Bex doesn't respond.","\n",{"->":"night_1.the_figure_appears"},{"#f":5}]}],{"#f":1}],"the_figure_appears":[["^11:15 PM.","\n","^Between groups, you stretch your neck and roll your shoulders. The boo hole is cramped. Your knees are stiff from standing. The mask is damp with condensation from your breath.","\n","^You look down the corridor through the window slit, watching the fog drift.","\n","^Someone is standing in the corridor.","\n","^Not moving. Not approaching. Just standing at the far end, where the corridor curves. They're in full costume: black base layer, a mask you don't recognize. Not The Collapse's cracked skull design. Something older. Rougher. Like burlap pulled over a face.","\n","^They're facing you.","\n","^You wait for them to move, to do something, to walk a group through. But there are no guests. The corridor is empty. It's a gap between groups. Nobody should be out there except Bex, and Bex is at their position to your left, out of your line of sight.","\n","^The figure stands there. Ten seconds. Twenty.","\n","ev","str","^Radio Bex.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Step out of the boo hole for a closer look.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Stay still and watch.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","ev",{"VAR?":"bex_relationship"},1,"+",{"VAR=":"bex_relationship","re":true},"/ev","^You key the radio to the zone channel. \"Bex. There's someone in my corridor. Far end, just standing there. Is that one of ours?\"","\n","^Two seconds of silence.","\n","^\"I don't see anyone.\"","\n","^You look again. The figure is still there.","\n","^\"End of the corridor. By the curve. They're in a mask I don't recognize.\"","\n","^A pause.","\n","^\"There's nobody scheduled past your position, Val. You're the last actor before the transition hallway.\"","\n",{"->":"night_1.figure_vanish"},{"#f":5}],"c-1":["\n","^You ease out of the alcove. The corridor stretches ahead of you, dimly lit, fog pooling on the floor. The figure is maybe forty feet away. You take a step toward them.","\n","^They don't move.","\n","^You take another step.","\n","^The ambient audio loops. The pickaxe sound. Dripping water. And underneath it, that hum. Louder down here than it was this afternoon.","\n",{"->":"night_1.figure_vanish"},{"#f":5}],"c-2":["\n","^You don't move. You watch through the slit. The figure doesn't move either. You try to make out details: height, build, anything. But the fog and the dim light flatten everything. They're just a shape. A silhouette that shouldn't be there.","\n",{"->":"night_1.figure_vanish"},{"#f":5}]}],{"#f":1}],"figure_vanish":[["^A group enters the corridor. You hear them coming: footsteps, whispers. The fog shifts.","\n","^You look back at the far end of the corridor.","\n","^The figure is gone.","\n","^Not walking away. Not stepping around the curve. Gone. The corridor is empty.","\n","^The group crosses your glow tape. Instinct takes over. You hit the window. You scream. They scream. Reset. Click.","\n","^But your hands are shaking.","\n","ev","str","^Finish the next few groups on autopilot.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_1.the_shift_changes"},{"#f":5}]}],{"#f":1}],"the_shift_changes":[["^11:50 PM.","\n","^You're rattled, but you keep working. Window. Scream. Reset. The rhythm steadies you. It's mechanical now. Your body does the job while your mind cycles through what you saw.","\n","^A figure in a costume nobody assigned. Standing motionless. Watching you. Vanishing.","\n","^This is a haunted attraction. People are in costume everywhere. It could have been an actor from another zone cutting through. A manager doing a walkthrough. Someone testing a new mask.","\n","^You almost convince yourself.","\n","^Then the corridor changes.","\n","^Between groups, during a longer lull after midnight, you lean out of the boo hole to stretch. You look left, toward Bex's position.","\n","^The corridor is different.","\n","^Not dramatically. Not impossibly. But the timber support that was ten feet to your left is now further away. Twenty feet, maybe. And there's a doorway in the wall between your position and Bex's that wasn't there during the tour. A doorway with no door, just a dark opening.","\n","ev","str","^Walk to the doorway.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Radio Bex.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^You remember what Bex said. The layout gets confusing after midnight. Stay in your zone.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n",{"->":"night_1.the_doorway"},{"#f":5}],"c-1":["\n","^\"Bex. Is there a doorway between our positions? In the left wall?\"","\n","^The radio hisses. Then: \"No.\"","\n","^\"I'm looking at one.\"","\n","^Silence. A long silence.","\n","^\"Stay in your hole, Val. Don't go through any doors that weren't there at the start of the shift.\"","\n","^The way they say it. Not confused. Not skeptical. Like this is advice they've had to give before.","\n",{"->":"night_1.post_midnight"},{"#f":5}],"c-2":["\n","^You pull back into the boo hole. You don't look at the doorway. The next group comes through and you hit the window and you scream and you do your job.","\n","^When you lean out again ten minutes later, the doorway is gone. The timber support is back where it was.","\n",{"->":"night_1.post_midnight"},{"#f":5}]}],{"#f":1}],"the_doorway":[["^You step into the corridor and walk to the doorway. Up close, it's rough stone. Not constructed. Carved, or maybe natural. The edges aren't clean. The air coming through it is warm and smells like copper.","\n","^Through the opening, you can see a narrow passage descending. No show lighting. No wiring. Just raw stone and darkness.","\n","^And the hum. Stronger here. Not just in your chest. In your teeth.","\n","ev","str","^Step through.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Look but don't enter.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^You take one step into the passage. The warmth wraps around you. The hum rises.","\n","^Then your radio crackles.","\n","^\"Zone 2 Bravo, we've got a group incoming. Return to your position.\" Floor manager. Routine voice. No urgency.","\n","^You step back out. The corridor is normal. Bex's timber support is where it should be. The doorway is still there. No. Wait.","\n","^It's gone.","\n","^You're standing in front of a solid stone wall.","\n","ev",{"VAR?":"erasure_level"},1,"+",{"VAR=":"erasure_level","re":true},"/ev",{"->":"night_1.post_midnight"},{"#f":5}],"c-1":["\n","^You stand at the threshold. The passage goes down. You can't see the bottom. The warm air pushes past you into the corridor, like breath from a mouth.","\n","^Your radio crackles. \"Group incoming, Zone 2.\"","\n","^You turn back. You return to your position. You don't look at the doorway again.","\n","^When the group has passed and you check, it's gone. Solid wall.","\n",{"->":"night_1.post_midnight"},{"#f":5}]}],{"#f":1}],"post_midnight":[["^The show runs until 2 AM.","\n","^The last two hours are a blur. Fewer groups, longer gaps. The energy in the attraction winds down. Your scream is hoarse. Your shoulder throbs. The edge of the mask has rubbed a raw line across the bridge of your nose.","\n","^Nothing else unusual happens. The corridor stays the way it should. No figure. No doorway. Just the job.","\n","^At 2:15, the house lights come on. The fog machines shut off. The ambient audio dies. The Hollows, in full fluorescent light, looks like what it is: a machine. Wiring. Plywood. Paint. The magic is gone. It's just a mine with props in it.","\n","^Bex appears next to you. They look the same as they did at 6 PM. Not tired. Not sweaty. Just present.","\n","^\"Good first night.\"","\n",["ev",{"^->":"night_1.post_midnight.0.12.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Thanks. My shoulder's going to hate me tomorrow.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.post_midnight.0.13.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I saw something.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.post_midnight.0.14.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Does it always feel like that? After midnight?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_1.post_midnight.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.12.s"},[{"#n":"$r2"}],"\n","^\"Switch to your left hand for the window after midnight. Alternate the strain. You'll last longer.\"","\n",{"->":"night_1.post_shift_walk"},{"#f":5}],"c-1":["ev",{"^->":"night_1.post_midnight.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.13.s"},[{"#n":"$r2"}],"\n","ev",{"VAR?":"bex_relationship"},1,"+",{"VAR=":"bex_relationship","re":true},"/ev","^Bex's expression doesn't change. \"Yeah.\"","\n","^They don't ask what.","\n",{"->":"night_1.post_shift_walk"},{"#f":5}],"c-2":["ev",{"^->":"night_1.post_midnight.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.14.s"},[{"#n":"$r2"}],"\n","^Bex starts walking toward the break room. \"It always feels like something after midnight.\"","\n",{"->":"night_1.post_shift_walk"},{"#f":5}]}],{"#f":1}],"post_shift_walk":[["^You change out of costume in the break room. The other actors are winding down. Some are laughing, comparing scares, replaying the best reactions. A guy in a werewolf mask tells a story about a woman who punched him in the chest. \"Solid hit. Respect.\" Everyone laughs.","\n","^It feels normal. It feels like a job you've worked before: the post-shift decompression, the shared exhaustion, the camaraderie of people who just spent six hours screaming in the dark.","\n","^But you keep glancing at the corridor. The one that leads down to the lower levels. From here, in the break room light, it just looks like a hallway.","\n","^The other actors leave in ones and twos. Bex is gone. You didn't see them go.","\n","^Dale's office door is closed. The light is off.","\n","^The break room is empty.","\n","ev","str","^Now's your chance. Access the staff terminal.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^You're exhausted. Go back to the motel and regroup.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n",{"->":"night_1.employee_records"},{"#f":5}],"c-1":["\n","^You can barely keep your eyes open. You'll investigate tomorrow.","\n",{"->":"night_1.end_night_1"},{"#f":5}]}],{"#f":1}],"employee_records":["^There's a staff computer in the corner of the break room. Ancient desktop, logged into a shared account. A scheduling program, a time clock application, an internal messaging system. Basic stuff.","\n","^You check over your shoulder. The corridor is empty. The building is quiet except for the ventilation system and, underneath it, the hum.","\n","^You open the scheduling program. Employee directory. Search.","\n","^Mara Castillo. No results.","\n","^Elena Voss. No results.","\n","^You try a broader search. All employees hired in the past two months. A list comes up: twelve names. You recognize a few from tonight's briefing. Your name is there. Val Rowan, hired today.","\n","^No Mara. No Elena. No gap in the records where someone was removed. It's not that her file was deleted. It's like the system never knew she existed.","\n","ev",true,"/ev",{"VAR=":"employee_records_seen","re":true},{"->":".^.^.records_hub"},{"#f":1}],"records_hub":[["^The terminal is still open. The building is still quiet. For now.","\n","ev","str","^Check the messaging system.","/str",{"CNT?":".^.^.^.records_messages"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Search for deleted or archived records.","/str",{"CNT?":".^.^.^.records_files"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Look up Bex.","/str",{"CNT?":".^.^.^.records_bex"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^Look up Dale.","/str",{"CNT?":".^.^.^.records_dale"},"!","/ev",{"*":".^.c-3","flg":21},"ev","str","^You've seen enough. Close out and leave.","/str",{"CNT?":".^.^.^.records_messages"},{"CNT?":".^.^.^.records_files"},"||",{"CNT?":".^.^.^.records_bex"},"||",{"CNT?":".^.^.^.records_dale"},"||","/ev",{"*":".^.c-4","flg":21},{"c-0":["\n",{"->":"night_1.records_messages"},{"#f":5}],"c-1":["\n",{"->":"night_1.records_files"},{"#f":5}],"c-2":["\n",{"->":"night_1.records_bex"},{"#f":5}],"c-3":["\n",{"->":"night_1.records_dale"},{"#f":5}],"c-4":["\n","^You clear the search history, close the programs, and step away from the terminal.","\n",{"->":"night_1.records_exit"},{"#f":5}]}],{"#f":1}],"records_messages":["^You open the internal messages. A shared inbox, mostly Dale sending shift reminders and schedule changes. You scroll back through three months of messages.","\n","^No mention of Mara. No mention of Elena. No mention of anyone leaving, being fired, or quitting. In three months of staffing a forty-person operation, not a single departure.","\n","^That's not normal.","\n",{"->":".^.^.records_hub"},{"#f":1}],"records_files":["^You poke around the file system. Temp folders, recycling bin, backup directories. You know what you're looking for: artifacts, fragments, anything that would indicate a record was removed.","\n","^Nothing. The database is clean. Too clean. Not scrubbed, but pristine, like it's never had an error, never had an edit, never had a correction.","\n","^No system that manages real humans looks like this.","\n",{"->":".^.^.records_hub"},{"#f":1}],"records_bex":["ev",true,"/ev",{"VAR=":"has_bex_file","re":true},"^You search for Bex. A single result: Bex. No last name. No hire date. The field is blank. Position: Rotating. Emergency contact: blank. Address: blank.","\n","^Every other employee has full records. Bex has a name and nothing else.","\n",{"->":".^.^.records_hub"},{"#f":1}],"records_dale":["ev",true,"/ev",{"VAR=":"has_dale_file","re":true},"^You search for Dale Ruskin. His file is immaculate.","\n","^Full name: Dale Arthur Ruskin. Position: General Manager. Hire date: March 3rd, 1998. The day The Hollows opened. Address: on-site staff housing. Emergency contact: HorrorCo Entertainment LLC, Corporate Office. No individual name. Salary: $187,000.","\n","^It's a lot of money for managing a haunted attraction in a town with one gas station.","\n","^You scroll down. Performance reviews. There are twenty-seven of them, one per year, going all the way back to 1998.","\n","^You open the most recent. \"Exceeds expectations. Dale continues to demonstrate exemplary leadership and operational excellence.\"","\n","^You open one from 2015. \"Exceeds expectations. Dale continues to demonstrate exemplary leadership and operational excellence.\"","\n","^Same. 2001. Same. 1999. Same. Word for word. Character for character.","\n","^You check his attendance record. No sick days. No vacation days. Not a single one. In twenty-seven years.","\n","^Either Dale Ruskin is the most dedicated employee in American history, or this file was written by something that doesn't understand what a real employment record looks like.","\n",{"->":".^.^.records_hub"},{"#f":1}],"records_exit":[["ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev","^You hear a sound from the corridor. Footsteps. Slow.","\n","^The break room door opens.","\n","^It's Dale. He glances at you.","\n","^\"Val!\"","\n","^\"Yeah. Just finishing up.\"","\n","^\"Building closes to staff at 3. Don't stay late.\" He holds the door open for you. It's not a suggestion.","\n","ev","str","^Leave.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_1.end_night_1"},{"#f":5}]}],{"#f":1}],"end_night_1":[["^3 AM.","\n","^You walk back to the Mineshaft Inn under a sky full of stars. The desert air is cold and dry and clean. It feels like surfacing.","\n","^The mine entrance is dark behind you. No lights. No fog. No sound.","\n","^Except the hum. Faint now, almost below perception. But there. You realize you've been hearing it since you arrived. You'll hear it in your sleep, if you sleep.","\n","^Room 6. You lock the door. You sit on the bed.","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ Mara was here. She worked here. She reported from inside this building. And now there's no record of her. Not deleted. Not hidden. Just... absent. Like she never was.",{"->":".^.^.^.18"},null]}],"nop","\n","ev",{"VAR?":"priority"},"str","^investigate_paranormal","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ The corridor changed. You saw it. A doorway that appeared and vanished. A figure that no one else saw. And underneath all of it, that hum. Something is down there.",{"->":".^.^.^.28"},null]}],"nop","\n","^You have questions. You don't have answers. But you have tomorrow.","\n","^You set your alarm for noon. You charge the burner phone on the nightstand.","\n","^You close your eyes.","\n","ev","str","^Day 2","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"day_2"},{"#f":5}]}],{"#f":1}],"#f":1}],"day_2":[{"->":".^.morning"},{"morning":[["^You wake up at noon. Your shoulder is stiff. Your throat is sore. Your nose has a raw stripe across the bridge from the mask.","\n","^Outside, the desert sun is high and white. Veinrock looks even smaller in daylight. Flat, bleached, empty.","\n","^You need towels. The ones in the room are thin and smell like dust. You walk to the motel office.","\n","^The owner is behind the counter. Same guy who checked you in. He looks up.","\n","^\"Help you?\"","\n",["ev",{"^->":"day_2.morning.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Could I get some fresh towels for room 6?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.morning.0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Morning.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_2.morning.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^He frowns. Looks at a clipboard.","\n","^\"Room 6? That room's vacant.\"","\n",{"->":"day_2.erasure_motel"},{"#f":5}],"c-1":["ev",{"^->":"day_2.morning.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^He stares at you. Polite, blank, waiting. The way you'd look at a stranger.","\n","^\"We met yesterday. You checked me in. Room 6.\"","\n",{"->":"day_2.erasure_motel"},{"#f":5}]}],{"#f":1}],"erasure_motel":[["ev",{"VAR?":"erasure_level"},1,"+",{"VAR=":"erasure_level","re":true},"/ev","^He flips through the clipboard. Runs his finger down the page.","\n","^\"I don't have anyone in room 6. You sure you're at the right place?\" He chuckles. \"Not a lot of options in town, but maybe you're thinking of somewhere down the highway.\"","\n","^You're holding the key. You show it to him. Room 6.","\n","^He looks at it. Looks at you. Something flickers behind his eyes. Confusion, maybe. Or the edge of a memory that can't quite take shape.","\n","^\"Huh. Must have, uh... let me check the system.\"","\n","^He types something into an ancient computer. Squints at the screen.","\n","^\"Oh, here we go. Val Rowan. Room 6. Sorry about that. Don't know how I missed it.\" He laughs again, uneasy this time. \"Long nights.\"","\n","^He hands you two towels.","\n",["ev",{"^->":"day_2.erasure_motel.0.22.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"No problem.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.erasure_motel.0.23.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Has that happened before? Forgetting a guest?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_2.erasure_motel.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.22.s"},[{"#n":"$r2"}],"\n","^You take the towels. You walk back to room 6. You close the door.","\n","^He didn't recognize you. For a moment, you didn't exist in his records. Then you did.","\n",{"->":"day_2.day_2_plans"},{"#f":5}],"c-1":["ev",{"^->":"day_2.erasure_motel.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.23.s"},[{"#n":"$r2"}],"\n","^\"Can't say it has.\" He rubs the back of his neck. \"Probably just need more coffee. You have a good day now.\"","\n","^He's already turning away.","\n",{"->":"day_2.day_2_plans"},{"#f":5}]}],{"#f":1}],"day_2_plans":["^You stand in the room. Burner phone in hand.","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ The motel owner forgot you. You've been here one night. Mara was here for ten days. If this happened to her too...",{"->":".^.^.^.10"},null]}],"nop","\n","ev",{"VAR?":"priority"},"str","^investigate_paranormal","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ The motel owner forgot you. You checked in less than thirty-six hours ago. Whatever is happening at The Hollows, it's not staying at The Hollows.",{"->":".^.^.^.20"},null]}],"nop","\n","^You have until 6 PM before your shift. Time to dig.","\n",{"->":".^.^.day_2_hub"},{"#f":1}],"day_2_hub":[["ev","str","^Go to Gloria's diner.","/str",{"CNT?":"day_2.day_2_gloria"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Look for a library or municipal office.","/str",{"CNT?":"day_2.day_2_library"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Call Silas.","/str",{"CNT?":"day_2.day_2_silas"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^Head to The Hollows for your shift.","/str",{"CNT?":"day_2.day_2_gloria"},{"CNT?":"day_2.day_2_library"},"||",{"CNT?":"day_2.day_2_silas"},"||","/ev",{"*":".^.c-3","flg":21},{"c-0":["\n",{"->":"day_2.day_2_gloria"},{"#f":5}],"c-1":["\n",{"->":"day_2.day_2_library"},{"#f":5}],"c-2":["\n",{"->":"day_2.day_2_silas"},{"#f":5}],"c-3":["\n",{"->":"day_2.day_2_end"},{"#f":5}]}],{"#f":1}],"day_2_silas":[["ev",{"VAR?":"silas_trust"},1,"+",{"VAR=":"silas_trust","re":true},"/ev","^You dial the burner. It rings four times. That's new. He used to pick up in one or two.","\n","^\"Ward.\"","\n","^\"It's me. I need to report.\"","\n","^You tell him about Night 1. The figure in the corridor. The shifting layout. ","ev",{"VAR?":"employee_records_seen"},"/ev",[{"->":".^.b","c":true},{"b":["^ The employee records with no trace of Mara.",{"->":".^.^.^.17"},null]}],"nop","^ The motel owner forgetting you this morning.","\n","^Silence on the line. Not thoughtful silence. Empty silence, like the signal is struggling.","\n","^\"The erasure...\" His voice cuts out for a moment, then comes back. \"...consistent with what Mara described in her final reports. She said people in town started looking through her. Like she was becoming transparent.\"","\n",["ev",{"^->":"day_2.day_2_silas.0.24.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"That's what's happening to me?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.day_2_silas.0.25.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"What else did Mara say in those final reports?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.day_2_silas.0.26.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"You didn't tell me about this during the briefing.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_2.day_2_silas.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.24.s"},[{"#n":"$r2"}],"\n","^\"I don't know. Maybe. She was there for ten days before it started. You're on day two.\" A pause. Static. \"It's accelerating.\"","\n",{"->":"day_2.silas_continued"},{"#f":5}],"c-1":["ev",{"^->":"day_2.day_2_silas.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.25.s"},[{"#n":"$r2"}],"\n","^\"She mentioned the hum. Said it was getting louder. She said she found a way into the lower levels but hadn't gone down yet. That was her last report.\"","\n",{"->":"day_2.silas_continued"},{"#f":5}],"c-2":["ev",{"^->":"day_2.day_2_silas.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.26.s"},[{"#n":"$r2"}],"\n","^A beat. When he speaks, his voice is careful.","\n","^\"I told you what I thought was relevant. I didn't want to bias your observations.\" Another beat. \"I should have told you.\"","\n","ev",{"VAR?":"silas_trust"},1,"+",{"VAR=":"silas_trust","re":true},"/ev",{"->":"day_2.silas_continued"},{"#f":5}]}],{"#f":1}],"silas_continued":["^\"Listen. I'm going to try to pull records on HorrorCo from our end. Corporate filings, property transfers, anything.\" The line crackles. \"But Val. The motel owner. If people are forgetting you already...\"","\n","^The signal drops to static for three full seconds.","\n","^\"...careful. Report again tomorrow.\"","\n","^The line goes dead. You're not sure if he hung up or if the call just stopped.","\n",{"->":".^.^.day_2_hub"},{"#f":1}],"day_2_gloria":["ev",{"VAR?":"day_1_gloria"},"/ev",[{"->":".^.b","c":true},{"b":["\n","^Gloria is behind the counter when you walk in. She glances up and, for just a moment, you think you see the same blankness the motel owner had. Then it clears.","\n","^\"You again.\" She pours you a coffee without asking. \"Sit down.\"","\n",{"->":".^.^.^.5"},null]}],[{"->":".^.b"},{"b":["\n","^The diner is called ALDRICH'S. Small, warm, mostly empty. Checkered floor, vinyl booths, a counter with stools. Hasn't been updated since the '80s.","\n","^The woman behind the counter is in her late 70s, maybe older. She moves with careful precision. Sharp eyes. Her name tag reads GLORIA.","\n","^She sets a coffee down in front of you before you ask for one.","\n","^\"You're new.\"","\n","^It's not a question.","\n",["ev",{"^->":"day_2.day_2_gloria.4.b.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"I just started at The Hollows.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.day_2_gloria.4.b.12.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I'm Val.\"",{"->":"$r","var":true},null]}],{"->":".^.^.^.5"},{"c-0":["ev",{"^->":"day_2.day_2_gloria.4.b.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^Something crosses her face. Fast, then gone.","\n","^\"Another one.\"","\n","^\"My name is Val.\"","\n",{"->":"day_2.gloria_day_2_hub"},{"#f":5}],"c-1":["ev",{"^->":"day_2.day_2_gloria.4.b.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.12.s"},[{"#n":"$r2"}],"\n","^\"Gloria.\" She doesn't offer a handshake. \"You working up at the mine?\"","\n",{"->":"day_2.gloria_day_2_hub"},{"#f":5}]}]}],"nop","\n",{"->":".^.^.gloria_day_2_hub"},{"#f":1}],"gloria_day_2_hub":[["ev","str","^Ask about the sinkhole.","/str",{"CNT?":"day_2.gloria_sinkhole"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Ask about HorrorCo.","/str",{"CNT?":"day_2.gloria_horrorco"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Ask about workers at The Hollows.","/str",{"CNT?":"day_2.gloria_workers"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^Thank her and leave.","/str",{"CNT?":"day_2.gloria_sinkhole"},{"CNT?":"day_2.gloria_horrorco"},"||",{"CNT?":"day_2.gloria_workers"},"||","/ev",{"*":".^.c-3","flg":21},{"c-0":["\n",{"->":"day_2.gloria_sinkhole"},{"#f":5}],"c-1":["\n",{"->":"day_2.gloria_horrorco"},{"#f":5}],"c-2":["\n",{"->":"day_2.gloria_workers"},{"#f":5}],"c-3":["\n",{"->":"day_2.gloria_day_2_end"},{"#f":5}]}],{"#f":1}],"gloria_sinkhole":[["ev",{"VAR?":"day_1_gloria"},"/ev",[{"->":".^.b","c":true},{"b":["\n","^\"You told me yesterday your father owned the mine.\"","\n","^Gloria wraps her hands around her mug. \"I did.\"","\n","^\"You said a sinkhole doesn't breathe.\"","\n","^She's quiet for a long moment. Studying you. Deciding something.","\n",{"->":".^.^.^.5"},null]}],[{"->":".^.b"},{"b":["\n","^\"What do you know about the mine? Before it was The Hollows?\"","\n","^Gloria sets down the pot. Leans against the counter.","\n","^\"My father owned the Aldrich Silver Mine. I was nine years old when the ground opened up and took it.\"","\n",{"->":".^.^.^.5"},null]}],"nop","\n","^\"The official report said geological instability. Subsurface void collapse. Natural causes.\" She says the words like she's reading from a document she's memorized against her will.","\n","^\"But I was standing in the yard when it happened. I heard it. Everyone heard it. The ground shook and then there was a sound.\" She pauses. \"Not a collapse sound. Not rock breaking.\"","\n",["ev",{"^->":"day_2.gloria_sinkhole.0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What kind of sound?\"",{"->":"$r","var":true},null]}],"ev","str","^Wait.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["ev",{"^->":"day_2.gloria_sinkhole.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n",{"->":"day_2.gloria_opened"},{"#f":5}],"c-1":["\n",{"->":"day_2.gloria_opened"},{"#f":5}]}],{"#f":1}],"gloria_opened":["^\"It opened.\" Her voice drops. \"That's the only word for it. The mine didn't collapse. It opened. Like something underneath had been pushing up for a long time and finally got through.\"","\n","^She looks at her hands.","\n","^\"Forty-eight men went down that shaft. The rescue teams went in three hours later. They found the shaft. They found the equipment. They found lunch pails sitting on rocks where the men had set them down.\"","\n","^\"But no bodies?\"","\n","^\"No bodies. No bones. No blood. Nothing. Forty-eight men, gone. Like they'd been erased.\"","\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev","ev",true,"/ev",{"VAR=":"has_gloria_testimony","re":true},{"->":".^.^.gloria_day_2_hub"},{"#f":1}],"gloria_horrorco":[["^\"What do you know about the company that built The Hollows?\"","\n","^Gloria's mouth tightens.","\n","^\"HorrorCo.\" She says it like a curse. \"They showed up in '98. Bought the mine, bought the land around it, bought half the buildings in town. Paid cash. Didn't negotiate.\"","\n","^\"Who did they buy from?\"","\n","^\"The county. The land had been in foreclosure for twenty years. Nobody wanted it. A mine that swallowed forty-eight men doesn't attract buyers.\" She pauses. \"Until it did.\"","\n",["ev",{"^->":"day_2.gloria_horrorco.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Did you ever meet anyone from HorrorCo?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.gloria_horrorco.0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Why did you stay?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_2.gloria_horrorco.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^\"Just Dale. He came into the diner the week they started construction. Introduced himself. Big smile. Told me they were going to put Veinrock back on the map.\" Her expression is flat. \"He looked exactly the same then as he does now. Twenty-seven years ago. Same face. Same smile. Same polo shirt.\"","\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev",{"->":"day_2.gloria_day_2_hub"},{"#f":5}],"c-1":["ev",{"^->":"day_2.gloria_horrorco.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^\"I left. After the mine. My mother took me to Reno. I grew up there. Went to school. Got married. Got divorced.\" She shrugs. \"But I kept coming back. Every few years, I'd drive out. Just to look. I can't explain it.\"","\n","^She stares at her coffee.","\n","^\"When HorrorCo opened the diner back up, they offered it to me. I don't know how they knew I existed. I don't know how they had my phone number. But they called, and I came back. And I've been here since.\"","\n",{"->":"day_2.gloria_day_2_hub"},{"#f":5}]}],{"#f":1}],"gloria_workers":[["^\"The people who work at The Hollows. Do they ever come in here?\"","\n","^\"Some of them. The new ones, mostly. They come in for a few weeks, excited, chatty. Then they come in less. Then they stop.\"","\n",["ev",{"^->":"day_2.gloria_workers.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Where do they go?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.gloria_workers.0.5.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Have you noticed anyone disappear?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_2.gloria_workers.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^\"Nowhere. They're still here. You'll see them walking to their shifts, walking back. But they stop coming in. Stop talking.\"","\n",{"->":"day_2.gloria_workers_more"},{"#f":5}],"c-1":["ev",{"^->":"day_2.gloria_workers.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.5.s"},[{"#n":"$r2"}],"\n","^Gloria is quiet for a while.","\n","^\"There was a young woman. About a month ago. Came in a few times. Dark hair, sharp eyes. Ordered the same thing every time: black coffee and the meatloaf.\"","\n","^Your stomach drops.","\n",{"->":"day_2.gloria_mara"},{"#f":5}]}],{"#f":1}],"gloria_workers_more":[["^\"And some of them have been there since the beginning. Since '98. They don't age right. They don't change. Bex...\" She stops herself.","\n",["ev",{"^->":"day_2.gloria_workers_more.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"You know Bex?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.gloria_workers_more.0.3.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"What do you mean, they don't age right?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_2.gloria_workers_more.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n","^\"Everyone in Veinrock knows Bex. Or knows of them. They've been at The Hollows as long as Dale has. Maybe longer, if that's possible.\" She leans forward. \"I don't think Bex knows how long they've been there. I think they've lost count. Or lost the ability to count.\"","\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev",{"->":"day_2.gloria_day_2_hub"},{"#f":5}],"c-1":["ev",{"^->":"day_2.gloria_workers_more.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.3.s"},[{"#n":"$r2"}],"\n","^\"I mean Dale Ruskin looked fifty years old in 1998 and he looks fifty years old now. I mean Bex looked twenty-five when the place opened and they look twenty-five today.\" She sets her jaw. \"I'm eighty-two. I know what aging looks like. Those people aren't doing it.\"","\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev",{"->":"day_2.gloria_day_2_hub"},{"#f":5}]}],{"#f":1}],"gloria_mara":[["ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ Your heart rate spikes. That's Mara. That's her.",{"->":".^.^.^.8"},null]}],"nop","\n","^\"Do you remember her name?\"","\n","^Gloria thinks. Frowns. Shakes her head slowly.","\n","^\"I should. She told me. She sat right where you're sitting. We talked.\" Gloria stares at the counter like she's trying to see through it. \"I can picture her face. I can hear her voice. But the name is just... gone.\"","\n",["ev",{"^->":"day_2.gloria_mara.0.16.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Her name was Mara.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.gloria_mara.0.17.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Did she say anything about the mine?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_2.gloria_mara.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.16.s"},[{"#n":"$r2"}],"\n","^Gloria looks at you sharply. \"How do you know that?\"","\n","^\"Because I'm here looking for her.\"","\n","^A long silence. Gloria's eyes are wet. Not crying. Just the strain of trying to hold onto something that's slipping away.","\n","^\"She asked me the same kinds of questions you're asking. About the mine. About HorrorCo.\" Her voice is barely above a whisper. \"And then she stopped coming in. And I forgot she existed until you just said her name.\"","\n","ev",{"VAR?":"gloria_trust"},2,"+",{"VAR=":"gloria_trust","re":true},"/ev","ev",{"VAR?":"mara_clues"},1,"+",{"VAR=":"mara_clues","re":true},"/ev",{"->":"day_2.gloria_day_2_hub"},{"#f":5}],"c-1":["ev",{"^->":"day_2.gloria_mara.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.17.s"},[{"#n":"$r2"}],"\n","^\"She was interested in the history. The sinkhole. Asked a lot of questions.\" Gloria pauses. \"Smart questions. Like she already knew some of the answers and was testing mine.\"","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ That sounds like Mara.",{"->":".^.^.^.17"},null]}],"nop","\n","ev",{"VAR?":"mara_clues"},1,"+",{"VAR=":"mara_clues","re":true},"/ev",{"->":"day_2.gloria_day_2_hub"},{"#f":5}]}],{"#f":1}],"gloria_day_2_end":[["^Gloria clears your coffee cup.","\n","ev",{"VAR?":"gloria_trust"},3,">=","/ev",[{"->":".^.b","c":true},{"b":["^ \"Val.\" She says your name like she's committing it to memory. \"Be careful in that mine. And come back tomorrow. I have something to show you.\"",{"->":".^.^.^.8"},null]}],"nop","\n","ev",{"VAR?":"gloria_trust"},3,"<","/ev",[{"->":".^.b","c":true},{"b":["^ \"You should eat before your shift. You look thin.\" She slides a menu across the counter. It's not warmth, exactly. But it's close.",{"->":".^.^.^.16"},null]}],"nop","\n",["ev",{"^->":"day_2.gloria_day_2_end.0.18.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"VAR?":"gloria_trust"},3,">=","/ev",{"*":".^.^.c-0","flg":19},{"s":["^\"I will.\"",{"->":"$r","var":true},null]}],"ev","str","^Eat and leave.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["ev",{"^->":"day_2.gloria_day_2_end.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.18.s"},[{"#n":"$r2"}],"\n",{"->":"day_2.day_2_hub"},{"#f":5}],"c-1":["\n","^The meatloaf is","ev",{"VAR?":"day_1_gloria"},"/ev",[{"->":".^.b","c":true},{"b":["^ still",{"->":".^.^.^.6"},null]}],"nop","^ decent.","\n",{"->":"day_2.day_2_hub"},{"#f":5}]}],{"#f":1}],"day_2_library":["^The Veinrock Public Library is a single room in the back of the municipal building, which is itself a converted house. The sign out front still says HENDERSON RESIDENCE underneath the county seal.","\n","^Inside: four shelves of donated paperbacks, a microfiche reader that probably hasn't been turned on since the '90s, and a desk where a part-time clerk sits reading a magazine. She doesn't look up when you enter.","\n","^The local history section is half a shelf. But it's enough.","\n",{"->":".^.^.library_hub"},{"#f":1}],"library_hub":[["ev","str","^Look for coverage of the 1973 sinkhole.","/str",{"CNT?":"day_2.library_sinkhole"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Look for records of HorrorCo's purchase.","/str",{"CNT?":"day_2.library_horrorco"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Check the town census or directories.","/str",{"CNT?":"day_2.library_census"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^You've seen enough. Leave.","/str",{"CNT?":"day_2.library_sinkhole"},{"CNT?":"day_2.library_horrorco"},"||",{"CNT?":"day_2.library_census"},"||","/ev",{"*":".^.c-3","flg":21},{"c-0":["\n",{"->":"day_2.library_sinkhole"},{"#f":5}],"c-1":["\n",{"->":"day_2.library_horrorco"},{"#f":5}],"c-2":["\n",{"->":"day_2.library_census"},{"#f":5}],"c-3":["\n",{"->":"day_2.library_end"},{"#f":5}]}],{"#f":1}],"library_sinkhole":[["ev",true,"/ev",{"VAR=":"has_sinkhole_history","re":true},"^You find a bound collection of the Veinrock Gazette, which apparently ran from 1924 to 1974. The final year has only three issues.","\n","^The sinkhole is front page of the June 15, 1973 edition. ALDRICH MINE COLLAPSE KILLS 48. The article describes the event in dry, factual language. Geological instability. Emergency crews dispatched. No survivors recovered.","\n","^But there's a detail in the third paragraph that stops you.","\n","^\"Rescue teams reported that the main shaft, previously measured at 340 feet in depth, now extended beyond the reach of available sounding equipment. Foreman Bill Husted described the shaft as 'bottomless,' though county geologists attributed this to instrument malfunction.\"","\n","^The mine got deeper when it collapsed.","\n","ev","str","^Keep reading.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Note the depth detail and move on.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^The next issue, dated three weeks later, is mostly obituaries. Forty-eight names. Forty-eight families. The town's entire working-age male population.","\n","^The final issue, September 1974, is a single page. VEINROCK POST OFFICE TO CLOSE. The last sentence reads: \"No forwarding addresses were provided.\"","\n",{"->":"day_2.library_hub"},{"#f":5}],"c-1":["\n","^You write it down. 340 feet, then bottomless. Mines don't get deeper when they collapse. They get shallower.","\n",{"->":"day_2.library_hub"},{"#f":5}]}],{"#f":1}],"library_horrorco":[["ev",true,"/ev",{"VAR=":"has_horrorco_filing","re":true},"^The municipal records are in a filing cabinet by the desk. The clerk doesn't seem to care that you're going through them.","\n","^You find the property transfer. HorrorCo Entertainment LLC purchased the Aldrich Mine property and surrounding 200 acres from Nye County on February 12, 1998. Purchase price: $1.2 million, paid in full.","\n","^The filing includes HorrorCo's articles of incorporation. You check the date.","\n","^Incorporated in Delaware. June 22, 1973.","\n","^One week after the sinkhole.","\n","^HorrorCo was created seven days after forty-eight men vanished into the earth. Then it waited twenty-five years to come back and build on top of the hole.","\n","ev","str","^Look for any names on the incorporation documents.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Note the dates and move on.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^The incorporator is listed as \"M. Aldrich, Registered Agent.\" Aldrich, like the mine. ","ev",{"CNT?":"day_2.day_2_gloria"},{"VAR?":"day_1_gloria"},"||","/ev",[{"->":".^.b","c":true},{"b":["^ Like Gloria's family. But Gloria said her family left town after the collapse. Who is M. Aldrich?",{"->":".^.^.^.8"},null]}],"nop","^ ","ev",{"CNT?":"day_2.day_2_gloria"},"!",{"VAR?":"day_1_gloria"},"!","&&","/ev",[{"->":".^.b","c":true},{"b":["^ The same name as the mine. A relative of the original owners? Someone else entirely?",{"->":".^.^.^.18"},null]}],"nop","\n","ev",{"VAR?":"mara_clues"},1,"+",{"VAR=":"mara_clues","re":true},"/ev",{"->":"day_2.library_hub"},{"#f":5}],"c-1":["\n","^You write it down. Incorporated one week after the sinkhole. Purchased the land twenty-five years later. Whatever HorrorCo is, it's been planning this for a long time.","\n",{"->":"day_2.library_hub"},{"#f":5}]}],{"#f":1}],"library_census":[["ev",true,"/ev",{"VAR=":"has_census_data","re":true},"^You find a shelf of county directories going back to the 1960s. You pull a few.","\n","^1970 directory: Veinrock, population 203. Four pages of names, addresses, occupations. A living town.","\n","^1975 directory: Veinrock, population 0. The entry is a single line. \"No registered residents.\"","\n","^1999 directory: Veinrock, population 47. You scan the names. Dale Ruskin. Bex (no surname). Gloria Aldrich. The rest you don't recognize. Most list their employer as HorrorCo Entertainment.","\n","^You cross-reference with the 2010 directory. Population: 51. Many of the same names. Dale Ruskin. Bex. Gloria. A few additions. No deletions.","\n","^The 2020 directory. Population: 54. Same core names. Same addresses. A few more additions.","\n","^In twenty years, the town has gained seven people and lost zero.","\n","^Nobody has died. Nobody has moved away. In a town of fifty people, over two decades, not a single person has left.","\n","ev",{"CNT?":"day_2.day_2_silas"},"/ev",[{"->":".^.b","c":true},{"b":["^ Except the ones who vanished.",{"->":".^.^.^.24"},null]}],"nop","\n","ev","str","^Check if any of the current residents match the 1970 names.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Note it and move on.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^You compare the lists. None of the 1999 names appear in 1970. The old Veinrock and the new Veinrock share nothing except the name and Gloria Aldrich.","\n",{"->":"day_2.library_hub"},{"#f":5}],"c-1":["\n","^You write it down. A town where nobody leaves and nobody dies. That's not a town. That's something else.","\n",{"->":"day_2.library_hub"},{"#f":5}]}],{"#f":1}],"library_end":["^You put the records back where you found them. The clerk is still reading her magazine. She hasn't looked at you once.","\n","^At the door, you glance back. The clerk is watching you. She looks away quickly.","\n","ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev","^Or maybe she was never looking. Maybe you imagined it.","\n",{"->":".^.^.day_2_hub"},{"#f":1}],"day_2_end":[["^Late afternoon. The sun is dropping. The temperature is already falling. The desert cools fast.","\n","^You walk to The Hollows. The parking lot is starting to fill. A line is forming at the ticket booth. Families, couples, groups of teenagers. People who drove hours to be here. People who want to be scared.","\n","^You pass them on the way to the staff entrance. One of them, a kid maybe ten years old, watches you walk by.","\n","^\"Are you one of the monsters?\" he asks.","\n",["ev",{"^->":"day_2.day_2_end.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Not yet.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.day_2_end.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Only at night.\"",{"->":"$r","var":true},null]}],"ev","str","^Just smile and keep walking.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"day_2.day_2_end.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n","^The kid grins. His mother pulls him back into line.","\n",{"->":"night_2"},{"#f":5}],"c-1":["ev",{"^->":"day_2.day_2_end.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n","^The kid's grin falters for a second, then comes back wider.","\n",{"->":"night_2"},{"#f":5}],"c-2":["\n",{"->":"night_2"},{"#f":5}]}],{"#f":1}],"#f":1}],"night_2":[{"->":".^.costume_room_2"},{"costume_room_2":[["^The costume room is loud tonight. Music from someone's phone. Two actors arguing about the best way to do a drop scare. The woman with the ribcage piece is back, adjusting the lung mechanism with a screwdriver.","\n","^Bex is at their usual station. They nod when they see you.","\n","^\"You're in a new zone tonight. The Shaft. Dale wants to see how you handle movement.\"","\n",["ev",{"^->":"night_2.costume_room_2.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What kind of movement?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_2.costume_room_2.0.7.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Why the move?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_2.costume_room_2.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Are you in The Shaft too?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_2.costume_room_2.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","^\"Stalker walk. You follow groups through the corridor. Match their pace, stay behind them, don't make a sound until they notice you. When they run, you stop. Reset. Wait for the next group.\"","\n",{"->":"night_2.costume_2_continued"},{"#f":5}],"c-1":["ev",{"^->":"night_2.costume_room_2.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.7.s"},[{"#n":"$r2"}],"\n","^\"Dale rotates new hires through the zones. Wants to see what you're good at.\" Bex pauses. \"Also, The Shaft is short-staffed tonight.\"","\n",{"->":"night_2.costume_2_continued"},{"#f":5}],"c-2":["ev",{"^->":"night_2.costume_room_2.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n","^\"No. I'm in The Collapse. Your old spot.\" Something in the way they say it. Like it's always been their spot. Like you were borrowing it.","\n",{"->":"night_2.costume_2_continued"},{"#f":5}]}],{"#f":1}],"costume_2_continued":["^The costume is the same mining jumpsuit, same mask, same greasepaint. Bex reapplies the prosthetic gash on your forehead, faster this time.","\n","^\"The Shaft is different from The Collapse. Longer corridors. Higher ceilings. You've got more room to work, but the guests can see further ahead, so you need to be smart about where you reveal.\"","\n","^They hand you a pair of soft-soled boots.","\n","^\"Swap these in. Your regular shoes are too loud on the stone. In The Shaft, silence is the whole game.\"","\n",{"->":".^.^.shaft_briefing"},{"#f":1}],"shaft_briefing":[[["ev",{"^->":"night_2.shaft_briefing.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_2.shaft_technique"},"!","/ev",{"*":".^.^.c-0","flg":19},{"s":["^\"Any tips for the stalker walk?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_2.shaft_briefing.0.1.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_2.shaft_layout"},"!","/ev",{"*":".^.^.c-1","flg":19},{"s":["^\"What's the layout?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_2.shaft_briefing.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_2.shaft_partner"},"!","/ev",{"*":".^.^.c-2","flg":19},{"s":["^\"Am I working with a partner?\"",{"->":"$r","var":true},null]}],"ev","str","^Ready.","/str","/ev",{"*":".^.c-3","flg":20},{"c-0":["ev",{"^->":"night_2.shaft_briefing.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":"night_2.shaft_technique"},{"#f":5}],"c-1":["ev",{"^->":"night_2.shaft_briefing.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.1.s"},[{"#n":"$r2"}],"\n",{"->":"night_2.shaft_layout"},{"#f":5}],"c-2":["ev",{"^->":"night_2.shaft_briefing.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n",{"->":"night_2.shaft_partner"},{"#f":5}],"c-3":["\n",{"->":"night_2.run_through_2"},{"#f":5}]}],{"#f":1}],"shaft_technique":["^\"Start far back. Twenty feet minimum. Match their speed exactly. Most groups walk slow in the dark, so you walk slow. Don't speed up until they do.\"","\n","^Bex demonstrates, taking three steps across the costume room floor. Completely silent. Their weight rolls from heel to toe. No impact. No scuff.","\n","^\"When the last person in the group notices you, freeze. Don't move. Half the time they'll convince themselves they imagined it and keep walking. Then you start again. Closer.\"","\n","^\"What if they freak out?\"","\n","^\"They will. When they run, you stop. You don't chase. Let the panic do the work. By the time they hit the next scare zone, they're already wired.\"","\n",{"->":".^.^.shaft_briefing"},{"#f":1}],"shaft_layout":["^\"One long main corridor, about a hundred and fifty feet. Curved slightly, so guests can't see the end from the entrance. There are three alcoves along the right wall where you can stage before stepping out. Your start position is alcove one, near the entrance.\"","\n","^Bex traces the layout on the makeup counter with their finger.","\n","^\"Guests enter from the south end. They walk through. You follow. At the north end, they turn left into the next zone. You peel off into the reset corridor and loop back to alcove one.\"","\n","^\"How long is the loop?\"","\n","^\"About forty-five seconds if you walk fast.\"","\n",{"->":".^.^.shaft_briefing"},{"#f":1}],"shaft_partner":[["^\"You're solo in The Shaft. There's a boo hole actor at the far end, but you won't interact with them. You're the only stalker.\"","\n",["ev",{"^->":"night_2.shaft_partner.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Solo on my second night?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_2.shaft_partner.0.3.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Got it.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_2.shaft_partner.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n","^\"You'll be fine. The walk is instinct once you get the timing down. And if you're stuck, just stand still. Standing still in the dark is scary enough.\"","\n",{"->":"night_2.shaft_briefing"},{"#f":5}],"c-1":["ev",{"^->":"night_2.shaft_partner.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.3.s"},[{"#n":"$r2"}],"\n",{"->":"night_2.shaft_briefing"},{"#f":5}]}],{"#f":1}],"run_through_2":[["^6:45 PM. Pre-show briefing. Dale does the speech. Same words. Same clipboard. Same smile.","\n","^\"Make it real, people.\"","\n","^The actors disperse. You catch a glimpse of the guy from last night, the one in the werewolf getup who told the punching story. He's at a station across the room, pulling on the same suit.","\n","^You raise a hand. A wave, a nod, the kind of casual acknowledgment between coworkers on night two.","\n","^He looks at you. Blank. Friendly, but blank. The way you look at someone you've never met. He gives a polite half-wave back and turns to his mirror.","\n","ev","str","^Maybe he just didn't recognize you in makeup.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Play it cool. Note it.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Walk over and reintroduce yourself.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","^That's possible. You look different in costume. Everyone does. It's only your second night. You barely spoke. There's no reason he'd remember you specifically.","\n","^That's probably all it is.","\n",{"->":"night_2.enter_shaft"},{"#f":5}],"c-1":["\n","^You file it away. The motel owner this morning. Now this. Maybe it's nothing. You're new. People don't always register new faces right away.","\n","^But that's twice today someone has looked right through you.","\n",{"->":"night_2.enter_shaft"},{"#f":5}],"c-2":["\n","^You walk to his station. \"Hey. Val. We met last night after the shift. You told the story about the woman who punched you.\"","\n","^He squints at you. Thinks. Then his face lights up.","\n","^\"Oh, right! Yeah, sorry. Didn't recognize you with the...\" He gestures at your makeup. \"Long nights, you know?\"","\n","^It sounds right. It probably is right.","\n","ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev",{"->":"night_2.enter_shaft"},{"#f":5}]}],{"#f":1}],"enter_shaft":[["^The Shaft is deeper in the upper level than The Collapse. The ceilings are higher here, the walls further apart. The corridor stretches ahead of you in a gentle curve, lit in a faint blue-white wash that makes the fog look like smoke. The set dressing is sparse: timber supports, a few mining tools bolted to the walls, a rusted ore cart shoved into a recess. The design relies on the space itself. The emptiness. The length of the corridor and the darkness at the far end.","\n","^Your start position is alcove one: a shallow cutout in the right wall, about four feet deep. Enough to hide in if you press flat against the stone.","\n","^You test the acoustics. Clap once. The sound travels a long way down the corridor, bouncing off the stone, dying slowly. In here, every footstep matters.","\n","^You swap into the soft-soled boots. Step. Step. Nothing. Good.","\n","^Radio crackle. \"Doors open in two. Positions, everyone.\"","\n","^You press into alcove one. You wait.","\n","ev","str","^Showtime.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_2.first_stalk"},{"#f":5}]}],{"#f":1}],"first_stalk":[["^The first group enters The Shaft at 8:04 PM.","\n","^Five people. Mid-twenties, mixed group. They're bunched together, moving cautiously. One of them has a hand on the person in front of them. The fog curls around their ankles. Their flashlight (phone, you realize, against the rules but nobody enforces it) throws a shaky beam that doesn't reach more than ten feet.","\n","^They pass alcove one. They don't see you.","\n","^You count to three. Then you step out.","\n","^The soft boots are silent on the stone. You match their pace. Slow. Deliberate. About fifteen feet behind the last person.","\n","^The corridor is long. They walk. You walk. The fog drifts between you and them. The ambient audio murmurs: dripping water, the groan of timber, a faint wind that doesn't exist.","\n","^The person at the back of the group glances over their shoulder.","\n","^You freeze.","\n","^They stare into the darkness behind them. The blue-white wash makes the fog glow. You're standing perfectly still, fifteen feet back, a dead miner in the haze.","\n","^\"There's something back there,\" they whisper.","\n","^\"Stop it,\" someone else says.","\n","^They turn forward. They keep walking. Faster now.","\n","^You wait two seconds. Then you start again. Closer. Ten feet.","\n","^The back person looks again. This time they see you clearly.","\n","^The scream is immediate. The group bolts. Their footsteps slap off the stone, echoing, overlapping. They round the curve and disappear into the next zone.","\n","^You stand in the empty corridor. Fog. Silence. The ambient audio loops.","\n","^You turn and walk back to alcove one.","\n","ev","str","^Reset. Wait. Do it again.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_2.stalk_rhythm"},{"#f":5}]}],{"#f":1}],"stalk_rhythm":[["^The stalker walk is a different discipline than the boo hole. In the boo hole, you were a mechanism. Trigger, fire, reset. In The Shaft, you're a presence. You have to feel the group's energy, adjust your distance, control your breath. Move too fast and you break the tension. Move too slow and they never notice you.","\n","^After about ten groups, you start to find it.","\n","^The soft boots help. You learn to step on the exhale, to shift your weight without lifting your feet fully off the stone. You learn to read the groups by their silhouettes: the nervous ones (hunched, tight cluster, hands on shoulders) and the brave ones (spread out, talking, daring each other). The nervous ones you let get halfway down the corridor before you step out. The brave ones you start early and close distance fast.","\n","^One group, a pair of teenage boys, doesn't scare at all. They see you and laugh. \"Bro, he's just standing there.\" You don't react. You just follow. Silent. Matching their pace exactly. By the time they reach the curve, they're not laughing anymore.","\n","^This is the job. Patient. Physical. Precise. Your legs ache from the controlled pace. Your jaw is tight from clenching against the urge to breathe too loud. Sweat pools under the mask.","\n","^By 10 PM, you've done maybe thirty groups. You're in the rhythm.","\n","ev","str","^Keep working.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_2.shaft_figure"},{"#f":5}]}],{"#f":1}],"shaft_figure":[["^10:40 PM.","\n","^A lull. Two minutes between groups. You're standing in alcove one, rolling your neck, flexing your toes in the soft boots.","\n","^You look down the corridor toward the far end. The blue-white wash fades to nothing around the curve. The fog is thin right now, pooling low.","\n","^Someone is standing in the corridor.","\n","^Not at the far end this time. Maybe thirty feet away. In the middle of the passage, directly in your sightline.","\n","^Same as last night. Black base layer. A mask that doesn't belong to any zone: rough, shapeless, like burlap stitched over a face. Standing perfectly still.","\n","^But tonight you notice something you couldn't see at distance last night. The costume underneath isn't a costume. It's a mining jumpsuit. Not distressed by a costume department. Old. Actually old. The fabric is stiff and faded in a way that takes decades, not a spray bottle and a sanding block. The stitching is wrong for modern clothing. The cut is wrong.","\n","^It looks like something from the '70s.","\n","ev",{"VAR?":"mara_clues"},0,"==","/ev",[{"->":".^.b","c":true},{"b":["^ That's all you can make out. The light is too low for more detail.",{"->":".^.^.^.22"},null]}],"nop","\n","ev",{"VAR?":"mara_clues"},1,"==","/ev",[{"->":".^.b","c":true},{"b":["^ Something about the figure's build nags at you. The height. The posture. You can't place it, but there's a familiarity you can't explain. Like a face you've seen in a photograph but never in person.",{"->":".^.^.^.30"},null]}],"nop","\n","ev",{"VAR?":"mara_clues"},2,">=","/ev",[{"->":".^.b","c":true},{"b":["^ The figure's height. The way they hold their shoulders, slightly forward, like someone who's used to leaning over a desk. You've seen that posture before. In a photograph Silas showed you. Mara Castillo was 5'6\" and left-handed and stood exactly like that.",{"->":".^.^.^.38"},null]}],"nop","\n","ev","str","^Step toward them.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Radio the floor manager.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Stay in the alcove. Watch.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","^You leave the alcove. One step. Two. The figure doesn't move. The fog curls between you.","\n","^You're close enough now to see that the burlap mask has no eye holes. The fabric is unbroken. Whoever is under there can't see.","\n","^But they're facing you.","\n",{"->":"night_2.figure_vanish_2"},{"#f":5}],"c-1":["\n","^You key the radio. \"Shaft stalker. I've got someone in my corridor. Thirty feet out. Not a scheduled actor.\"","\n","^Static. Then: \"Copy. We'll check it out.\"","\n","^Nobody comes.","\n",{"->":"night_2.figure_vanish_2"},{"#f":5}],"c-2":["\n","^You press against the stone and watch. The figure stands in the corridor. You count. Ten seconds. Twenty. Thirty. They don't shift their weight. They don't breathe visibly. They just stand.","\n","^The jumpsuit has a name patch on the chest. You squint. The light is too low. You can almost read it.","\n",{"->":"night_2.figure_vanish_2"},{"#f":5}]}],{"#f":1}],"figure_vanish_2":[["^Footsteps from the entrance. A new group. You hear them whispering, shuffling into The Shaft.","\n","^You look back at the figure.","\n","^Gone. Same as last night. Not departed. Just absent.","\n","^The group comes around the first bend. You step out. You follow. You do your job.","\n","^But your hands aren't shaking this time. Whatever this is, it's consistent. It follows a pattern. It appears in the gaps. It watches. It leaves.","\n","^You're not scared anymore. You're paying attention.","\n","ev","str","^Continue the shift.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_2.maintenance_discovery"},{"#f":5}]}],{"#f":1}],"maintenance_discovery":[["^11:20 PM.","\n","^Between groups, you're in alcove three. The last staging point before the curve. You've been cycling through all three alcoves to vary your reveal points.","\n","^Alcove three is the deepest. You press against the back wall and feel something behind you that isn't stone. Metal. A grate.","\n","^You turn and look. It's a maintenance access panel, about two feet square, bolted into the wall at floor level. One of the bolts is missing. Two others are loose, the threads stripped. The fourth holds, barely.","\n","^Warm air pushes through the gaps in the grate. And the hum. Louder through the grate than anywhere else in The Shaft.","\n","^A group enters the corridor. You step out, do the walk, send them running. Loop back.","\n","^The grate is still there. You crouch and test the remaining bolt with your fingers. It turns.","\n","ev","str","^Pull the grate off and go through.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Leave it for now. You know it's here.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Radio Bex about it.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","^You wait for a gap between groups. Radio chatter suggests a slowdown at the entrance. You have maybe three minutes.","\n","^You pull the last bolt free. The grate swings open on a corroded hinge you didn't see. The opening is tight. You set the grate against the wall, lower yourself to the ground, and squeeze through.","\n",{"->":"night_2.restricted_passage"},{"#f":5}],"c-1":["\n","^You memorize the location. Alcove three, The Shaft. You have a way in. But not tonight. Not in the middle of a shift with floor managers on the radio.","\n",{"->":"night_2.shaft_late"},{"#f":5}],"c-2":["\n","ev",{"VAR?":"bex_relationship"},1,"+",{"VAR=":"bex_relationship","re":true},"/ev","^You switch to a private channel. \"Bex. There's a maintenance access in alcove three of The Shaft. Grate's loose. Warm air coming through. The hum is stronger here.\"","\n","^A long pause.","\n","^\"Don't go through it, Val.\"","\n","^\"Why?\"","\n","^\"Because you might not come back to the same corridor.\"","\n","^Another pause.","\n","^\"Or the same night.\"","\n",{"->":"night_2.maintenance_choice_2"},{"#f":5}]}],{"#f":1}],"maintenance_choice_2":[["ev","str","^Go through anyway.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Heed the warning. Leave it for now.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^You wait for a gap between groups. You pull the bolt. The grate swings open. You squeeze through.","\n",{"->":"night_2.restricted_passage"},{"#f":5}],"c-1":["\n",{"->":"night_2.shaft_late"},{"#f":5}]}],{"#f":1}],"restricted_passage":[["^The passage is narrow. Not a vent. An old maintenance tunnel, maybe an air shaft for the original mine. The walls are rough stone, unfinished, no concrete or plywood. Your shoulders brush both sides. You half-crawl, half-shuffle forward.","\n","^The warm air is stronger here. It smells like copper and ozone. The hum fills the space, vibrating through the stone and into your palms where they press against the ground.","\n","^After about twenty feet, the passage opens up. You can stand. Barely.","\n","^You're in a section of tunnel that is not part of The Hollows.","\n","^No show lighting. No speakers. No fog machines. Just bare stone and a single emergency light mounted on the wall, casting a yellow circle on the ground. It buzzes faintly.","\n","^The floor is rough. Nobody has been through here recently. Except...","\n","ev","str","^Look around.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_2.restricted_findings"},{"#f":5}]}],{"#f":1}],"restricted_findings":["^The walls.","\n","^Someone has carved symbols into the stone. Not scratched casually. Carved, with deliberation and force. They cover a section of wall about three feet wide, arranged in concentric arcs. Angular, geometric, nothing you recognize. Some are simple: intersecting lines, circles with radiating points. Others are dense and layered, shapes nested inside shapes. They have a structure to them, a grammar, even if you can't read it.","\n","^The stone around the carvings is smooth, almost polished, as if the symbols have been traced by hand over and over again. Or as if the stone itself has responded to them.","\n","^Below the symbols, scratched in a different hand, rougher, more recent: a single word. OPEN.","\n",{"->":".^.^.notebook_page"},{"#f":1}],"notebook_page":[["^Something on the ground catches your eye. A piece of paper, folded twice, wedged into a crack where the wall meets the floor. It's been here a while. The edges are soft with moisture.","\n","^You pull it out and unfold it.","\n","^It's a page from a notebook. The paper is gridded. The handwriting is small, precise, and partially smudged. Most of the text is in a shorthand you recognize immediately: Order notation. Mara's.","\n","ev",{"VAR?":"mara_clues"},1,"+",{"VAR=":"mara_clues","re":true},"/ev","^But the page isn't mostly text. It's a diagram. A copy of the symbols on the wall, painstakingly reproduced in hard pencil. She's drawn them arranged in their concentric arcs, same as the carvings, but on the page she's added annotations: small arrows connecting repeating elements, question marks next to symbols she couldn't identify, circles around patterns she thought were significant.","\n","^At the center of the diagram: a small, simple drawing. A circle with lines radiating downward from it. It takes you a moment to realize what it is.","\n","^A mine shaft opening. Viewed from above.","\n","^In the margin, in English, three notes in Mara's handwriting:","\n","^\"Found on wall in deep rooms. Repeated seven times.\"","\n","^\"Not decorative. Functional?\"","\n","^\"The symbols match the patterns in the stone around the\"","\n","^The sentence stops. The bottom of the page is torn.","\n","^She found these same symbols somewhere else first: the deep rooms. Then she found her way down here and found them again. She was mapping them. Comparing them.","\n","ev","str","^Pocket the page.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Study it for another moment.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","ev",true,"/ev",{"VAR=":"has_notebook_page","re":true},"^You fold it carefully and tuck it inside your jumpsuit. This is evidence. Mara was here. Mara found these symbols. Mara was trying to understand them.","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ She was this close. She made it further than you have. And then she stopped.",{"->":".^.^.^.15"},null]}],"nop","\n",{"->":"night_2.restricted_door"},{"#f":5}],"c-1":["\n","ev",true,"/ev",{"VAR=":"has_notebook_page","re":true},"^The symbols aren't random. Even without understanding them, you can see a structure. They repeat in sequences. They scale in size as they get closer to the center, as if describing something that narrows. Something that descends.","\n","^You pocket the page.","\n",{"->":"night_2.restricted_door"},{"#f":5}]}],{"#f":1}],"restricted_door":[["^The tunnel continues past the carved wall. You follow it for another ten feet.","\n","^It ends at a door.","\n","^Not a steel security door like the ones upstairs. A wooden door, old, heavy, set into a stone frame. The wood is dark and swollen with moisture. An iron handle, black with oxidation.","\n","^The door is warm. You hold your palm an inch from the surface. The heat radiates outward, steady, like a living thing on the other side is pressing against it.","\n","^The hum is loudest here. Not just in your chest and your teeth now. In your vision. The edges of the yellow light seem to pulse with it.","\n","ev","str","^Try the handle.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Don't touch it.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^The handle is warm to the touch. You grip it. Turn.","\n","^It doesn't move. Locked, or jammed, or held shut by something.","\n","^You press your ear against the wood. Through the door, underneath the hum, you hear something. Faint. Rhythmic. It could be machinery. It could be breathing. It could be footsteps, far below, going down.","\n",{"->":"night_2.leave_restricted"},{"#f":5}],"c-1":["\n","^Everything in you wants to try that handle. And something else in you, something older than curiosity, is telling you not to.","\n","^You stand in front of the door for ten seconds. The warmth washes over you. The hum fills the tunnel.","\n","^Then you turn around.","\n",{"->":"night_2.leave_restricted"},{"#f":5}]}],{"#f":1}],"leave_restricted":[["^Your radio crackles. Muffled through the stone, but audible.","\n","^\"All zones, we're in final push. Groups are still coming. Positions, everyone.\"","\n","^You need to get back.","\n","^You move through the maintenance tunnel, faster now. Squeeze through the grate. Pull it closed behind you. The bolt won't hold, but it sits in place well enough.","\n","^Alcove three. You press flat against the wall. Your heart is pounding. Your hands smell like copper from the stone.","\n","^A group enters the corridor. You step out. You follow.","\n","ev","str","^Finish the shift.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_2.shaft_late"},{"#f":5}]}],{"#f":1}],"shaft_late":["^The last stretch of the shift is mechanical. You do the walk. You match the pace. You freeze. They scream. You reset.","\n","ev",{"CNT?":".^.^.restricted_passage"},"/ev",[{"->":".^.b","c":true},{"b":["^ But your mind is in the tunnel behind the grate. The symbols on the wall. The diagram. The door. The warmth.",{"->":".^.^.^.6"},null]}],"nop","\n","ev",{"CNT?":".^.^.restricted_passage"},"/ev",[{"->":".^.b","c":true},{"b":["^ Mara was down there. She found the symbols. She was documenting them, analyzing them, trying to determine if they were functional. She was doing exactly what you would have done.",{"->":".^.^.^.12"},null]}],"nop","\n","ev",{"CNT?":".^.^.restricted_passage"},"/ev",[{"->":".^.b","c":true},{"b":["^ And then she was gone.",{"->":".^.^.^.18"},null]}],"nop","\n","ev",{"CNT?":".^.^.restricted_passage"},"!","/ev",[{"->":".^.b","c":true},{"b":["^ But your mind keeps drifting to the grate in alcove three. The warm air. The hum. Whatever is behind that wall, it's close. You can feel it.",{"->":".^.^.^.25"},null]}],"nop","\n","^The show ends at 2 AM. House lights up. Fog off. Silence.","\n",{"->":".^.^.post_shift_2"},{"#f":1}],"post_shift_2":[["^The break room is quiet tonight. Fewer actors lingering. People are tired. The weekend rush takes a toll.","\n","^You change out of costume. Scrub the greasepaint off. Your face is raw.","\n","^Bex is at their station, removing their own makeup. They don't look at you.","\n","ev",{"CNT?":".^.^.^.restricted_passage"},"/ev",[{"->":".^.b","c":true},{"b":["\n","^You want to tell Bex what you found. The symbols. The diagram. The door. But something stops you. Bex told you not to go through the grate. If they know you did, what happens?","\n",{"->":".^.^.^.10"},null]}],"nop","\n","ev","str","^Tell Bex what you found.","/str",{"CNT?":".^.^.^.restricted_passage"},"/ev",{"*":".^.c-0","flg":21},"ev","str","^Keep it to yourself for now.","/str",{"CNT?":".^.^.^.restricted_passage"},"/ev",{"*":".^.c-1","flg":21},"ev","str","^Head out.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","ev",{"VAR?":"bex_relationship"},1,"+",{"VAR=":"bex_relationship","re":true},"/ev","^You sit down next to them. \"I went through the grate.\"","\n","^Bex's hand stops mid-wipe. They don't look at you. A long silence.","\n","^\"What did you find?\"","\n","^\"Symbols carved into the wall. A page from a notebook. A door.\"","\n","^\"Did you open the door?\"","\n","^\"It was locked.\"","\n","^Bex exhales. You're not sure if it's relief.","\n","^\"Don't go back down there, Val.\" Their voice is quiet. \"Please.\"","\n","^It's the first time they've said please about anything.","\n",{"->":"night_2.end_night_2"},{"#f":5}],"c-1":["\n","ev",{"VAR?":"bex_relationship"},1,"-",{"VAR=":"bex_relationship","re":true},"/ev","^You don't mention the grate. You don't mention the tunnel. You sit and clean your makeup in silence.","\n","^Bex glances at you once. Their eyes drop to your hands. You realize too late that your fingers are still orange-brown from the copper dust on the tunnel walls.","\n","^Bex looks away. They don't say anything.","\n",{"->":"night_2.end_night_2"},{"#f":5}],"c-2":["\n",{"->":"night_2.end_night_2"},{"#f":5}]}],{"#f":1}],"end_night_2":[["^3 AM.","\n","^The walk back to the motel. Stars. Cold air. The mine entrance dark and still behind you.","\n","^The hum. It's louder now than last night. Or you're more attuned to it. You can't tell the difference and it might not matter.","\n","^Room 6. Door locked. Shades drawn.","\n","ev",{"VAR?":"has_notebook_page"},"/ev",[{"->":".^.b","c":true},{"b":["^ You take out Mara's notebook page and lay it on the nightstand. The diagram. The symbols. The torn edge where her thought was cut short.",{"->":".^.^.^.12"},null]}],"nop","\n","ev",{"VAR?":"has_notebook_page"},"/ev",[{"->":".^.b","c":true},{"b":["^ \"The symbols match the patterns in the stone around the\"",{"->":".^.^.^.18"},null]}],"nop","\n","ev",{"VAR?":"has_notebook_page"},"/ev",[{"->":".^.b","c":true},{"b":["^ Around the what? The portal? The door? The shaft itself?",{"->":".^.^.^.24"},null]}],"nop","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ Mara was in that tunnel. She was doing the work. She was close to something. And then the work stopped and so did she. You're following her footsteps. You need to make sure they don't lead to the same place.",{"->":".^.^.^.34"},null]}],"nop","\n","ev",{"VAR?":"priority"},"str","^investigate_paranormal","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ Symbols copied from the deep rooms. A door that radiates heat. The pieces are starting to connect, but the picture they're forming isn't one you recognize yet.",{"->":".^.^.^.44"},null]}],"nop","\n","^You set your alarm for noon.","\n","ev","str","^Day 3","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n","done",{"#f":5}]}],{"#f":1}],"#f":1}],"global decl":["ev",0,{"VAR=":"bex_relationship"},0,{"VAR=":"dale_suspicion"},false,{"VAR=":"employee_records_seen"},0,{"VAR=":"erasure_level"},false,{"VAR=":"day_1_gloria"},0,{"VAR=":"gloria_trust"},false,{"VAR=":"has_bex_file"},false,{"VAR=":"has_census_data"},false,{"VAR=":"has_dale_file"},false,{"VAR=":"has_gloria_testimony"},false,{"VAR=":"has_horrorco_filing"},false,{"VAR=":"has_notebook_page"},false,{"VAR=":"has_sinkhole_history"},0,{"VAR=":"mara_clues"},false,{"VAR=":"night_1_employee_records_checked"},"str","^","/str",{"VAR=":"priority"},1,{"VAR=":"silas_trust"},"/ev","end",null],"#f":1}],"listDefs":{}};